# Embedded copies that duplicate archify catalog ids. Not served at /brand/.
# postgres/node/gcp are the only renames; the other five catalog ids match.
_DROPPED_BRAND_CATALOG: dict[str, str] = {
    "docker": "docker",
    "kubernetes": "kubernetes",
    "postgres": "postgresql",
    "mysql": "mysql",
    "redis": "redis",
    "python": "python",
    "node": "node-js",
    "gcp": "google-cloud",
}
