# ~0.22 alpha on the node fill. 0x38/255 = 0.2196.
_NODE_FILL_ALPHA = 0.22
_LEGEND_HINT = (
    "Custom colors are bendwright presets. On a dark theme, green sits near "
    "backend, amber near cloud, teal near frontend, red near message bus, "
    "and gray near external."
)


def empty_sidecar() -> dict[str, Any]:
    return {
        "bendwright_sidecar": 1,
        "edges": {},
        "nodes": {},
        "types": {},
        "assignments": {},
    }


# Custom type ids. Never stored in node.type (that stays one of the 7).
_TYPE_ID_RE = re.compile(r"^[a-z][a-z0-9_-]*$")
_TYPE_LABEL_MAX = 80
_BUILTIN_TYPE_LABELS: dict[str, str] = {
    "frontend": "Frontend",
    "backend": "Backend",
    "database": "Database",
    "cloud": "Cloud",
    "security": "Security",
    "messagebus": "Message bus",
    "external": "External",
}


def _builtin_type_ids() -> set[str]:
    return set(STATIC_ENUMS["node.type"])


def type_library_path() -> Path:
    """User-level type library at bendwright-data/types.json."""
    return data_dir() / "types.json"


def empty_type_library() -> dict[str, Any]:
    return {"bendwright_types": 1, "types": []}


def _type_color_ok(entry: dict[str, Any]) -> bool:
    if "color" not in entry or entry.get("color") in (None, "", "none"):
        return True
    _color, known = _classify_color(entry.get("color"))
    return known


def _type_record_ok(type_id: Any, entry: Any) -> bool:
    """id, label, base, and icon shape. Color is checked separately."""
    if not isinstance(type_id, str) or not _TYPE_ID_RE.fullmatch(type_id):
        return False
    if type_id in _builtin_type_ids():
        return False
    if not isinstance(entry, dict):
        return False
    base = entry.get("base")
    if not isinstance(base, str) or base not in _builtin_type_ids():
        return False
    label = entry.get("label")
    if not isinstance(label, str) or not label.strip() or len(label.strip()) > _TYPE_LABEL_MAX:
        return False
    if "icon" not in entry or entry.get("icon") in (None, "", "none"):
        return True
    icon = entry.get("icon")
    if not isinstance(icon, str) or len(icon) > 64 or any(ch.isspace() for ch in icon):
        return False
    return True


def _normalize_type_fields(type_id: str, entry: dict[str, Any]) -> dict[str, Any]:
    """Copy entry. Known fields normalized. Unknown keys kept."""
    out = copy.deepcopy(entry)
    out.pop("id", None)
    out["label"] = str(entry.get("label") or "").strip()
    out["base"] = entry.get("base")
    if "color" not in entry or entry.get("color") in (None, "", "none"):
        out["color"] = "none"
    else:
        color, _known = _classify_color(entry.get("color"))
        out["color"] = color or "none"
    icon = entry.get("icon", "none")
    if not isinstance(icon, str) or icon.strip() in ("", "none"):
        out["icon"] = "none"
    else:
        out["icon"] = icon.strip()
    return out


def load_type_library() -> tuple[dict[str, Any], str | None]:
    """Load bendwright-data/types.json. Missing file is an empty v1 library.

    Does not merge into a diagram. Unknown keys are kept. A newer version
    keeps unknown fields and returns a note.
    """
    path = type_library_path()
    if not path.is_file():
        return empty_type_library(), None
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        return (
            empty_type_library(),
            f"type library: could not read {path.name}; left the file untouched",
        )
    if not isinstance(data, dict):
        return (
            empty_type_library(),
            "type library: file is not a JSON object; left the file untouched",
        )
    stored = copy.deepcopy(data)
    notes: list[str] = []
    renamed = _migrate_type_icons(stored.get("types"))
    rename_note = _icon_rename_note(renamed)
    if rename_note:
        notes.append(rename_note)
    if "bendwright_types" not in stored and isinstance(stored.get("types"), list):
        stored["bendwright_types"] = 1
    version = stored.get("bendwright_types")
    if version not in (None, 1):
        notes.append(
            f"type library: newer bendwright_types version {version}; applied known fields"
        )
    if not isinstance(stored.get("types"), list):
        notes.append("type library: types is not a list; no library types offered")
    return stored, _join_notes(*notes) if notes else None


def save_type_in_library(raw: dict[str, Any]) -> tuple[dict[str, Any] | None, str | None]:
    """Upsert one type and atomically replace the library file.

    Unknown keys on the file and on the existing type entry are kept.
    """
    if not isinstance(raw, dict):
        return None, "type rejected: body must be an object"
    type_id = raw.get("id")
    if not _type_record_ok(type_id, raw):
        return None, (
            "type rejected: id must match ^[a-z][a-z0-9_-]*$, "
            "not be a built-in, and include a base and label"
        )
    if not _type_color_ok(raw):
        return None, "type rejected: unknown color"
    lib, note = load_type_library()
    types = lib.get("types")
    if not isinstance(types, list):
        types = []
        lib["types"] = types
    normalized = _normalize_type_fields(str(type_id), raw)
    replaced = False
    for index, entry in enumerate(types):
        if isinstance(entry, dict) and entry.get("id") == type_id:
            merged = copy.deepcopy(entry)
            for key, value in normalized.items():
                merged[key] = value
            merged["id"] = type_id
            _attach_library_icon_blob(merged)
            types[index] = merged
            replaced = True
            break
    if not replaced:
        fresh = copy.deepcopy(normalized)
        fresh["id"] = type_id
        _attach_library_icon_blob(fresh)
        types.append(fresh)
    if "bendwright_types" not in lib:
        lib["bendwright_types"] = 1
    path = type_library_path()
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        atomic_write(path, lib, True)
    except OSError as e:
        return None, f"type library write failed: {e}"
    return lib, note


def sidecar_path_for(ir_path: Path) -> Path:
    """Sibling sidecar. Same stem rule as export_html_path."""
    name = ir_path.name
    if name.endswith(".workflow.json"):
        stem = name[: -len(".workflow.json")]
    elif name.endswith(".json"):
        stem = name[: -len(".json")]
    else:
        stem = ir_path.stem
    return ir_path.parent / f"{stem}.bendwright.json"


def _edge_id_value(edge: dict[str, Any]) -> str:
    eid = edge.get("id")
    if isinstance(eid, str) and eid.strip():
        return eid
    return ""


def edge_style_key(edge: dict[str, Any], occurrence: int) -> str:
    eid = _edge_id_value(edge)
    if eid:
        return eid
    fr = edge.get("from") if isinstance(edge.get("from"), str) else ""
    to = edge.get("to") if isinstance(edge.get("to"), str) else ""
    return f"{fr}->{to}#{occurrence}"


def _edge_occurrence(edges: list[Any], index: int) -> int:
    edge = edges[index]
    if not isinstance(edge, dict) or _edge_id_value(edge):
        return 0
    fr = edge.get("from")
    to = edge.get("to")
    n = 0
    for earlier in edges[:index]:
        if not isinstance(earlier, dict) or _edge_id_value(earlier):
            continue
        if earlier.get("from") == fr and earlier.get("to") == to:
            n += 1
    return n


def iter_edge_style_keys(doc: dict[str, Any]) -> list[tuple[int, dict[str, Any], str]]:
    edges = doc.get("edges")
    if not isinstance(edges, list):
        return []
    found: list[tuple[int, dict[str, Any], str]] = []
    for i, edge in enumerate(edges):
        if not isinstance(edge, dict):
            continue
        found.append((i, edge, edge_style_key(edge, _edge_occurrence(edges, i))))
    return found


def _node_id_set(doc: dict[str, Any]) -> set[str]:
    nodes = doc.get("nodes")
    if not isinstance(nodes, list):
        return set()
    ids: set[str] = set()
    for node in nodes:
        if isinstance(node, dict) and isinstance(node.get("id"), str):
            ids.add(node["id"])
    return ids


def _classify_color(value: Any) -> tuple[str, bool]:
    """Return (preset or '', known). Missing / none is a known empty color."""
    if value is None or value in ("", "none"):
        return "", True
    if isinstance(value, str) and value in _STYLE_COLORS:
        return value, True
    return "", False


def _classify_dash(present: bool, value: Any) -> str | None:
    """Return solid|dashed|dotted, or None if the stored dash is unknown."""
    if not present or value is None or value == "":
        return "solid"
    if isinstance(value, str) and value in _STYLE_DASHES:
        return value
    return None


def _entry_is_dict(entry: Any) -> dict[str, Any] | None:
    if isinstance(entry, dict):
        return entry
    return None


def _style_skip_count(doc: dict[str, Any], sidecar: dict[str, Any]) -> int:
    """Unknown color/dash, a non-object entry, or a key no current element uses."""
    skipped = 0
    live_edges = {key for _i, _edge, key in iter_edge_style_keys(doc)}
    edges = sidecar.get("edges") if isinstance(sidecar, dict) else None
    if isinstance(edges, dict):
        for key, entry in edges.items():
            body = _entry_is_dict(entry)
            if body is None or key not in live_edges:
                skipped += 1
                continue
            _color, color_ok = _classify_color(body.get("color") if "color" in body else None)
            dash = _classify_dash("dash" in body, body.get("dash") if "dash" in body else None)
            if not color_ok or dash is None:
                skipped += 1
    elif edges is not None:
        skipped += 1

    live_nodes = _node_id_set(doc)
    nodes = sidecar.get("nodes") if isinstance(sidecar, dict) else None
    if isinstance(nodes, dict):
        for node_id, entry in nodes.items():
            body = _entry_is_dict(entry)
            if body is None or node_id not in live_nodes:
                skipped += 1
                continue
            _color, color_ok = _classify_color(body.get("color") if "color" in body else None)
            if not color_ok:
                skipped += 1
    elif nodes is not None:
        skipped += 1
    skipped += _type_skip_count(doc, sidecar)
    return skipped


def _assigned_type_body(sidecar: dict[str, Any], node_id: str) -> dict[str, Any] | None:
    """Valid custom type for this node, or None. Does not read the user library."""
    assignments = sidecar.get("assignments")
    types = sidecar.get("types")
    if not isinstance(assignments, dict) or not isinstance(types, dict):
        return None
    type_id = assignments.get(node_id)
    if not isinstance(type_id, str):
        return None
    entry = types.get(type_id)
    if not _type_record_ok(type_id, entry):
        return None
    return entry if isinstance(entry, dict) else None


def _inherited_type_color(sidecar: dict[str, Any], node_id: str) -> str:
    body = _assigned_type_body(sidecar, node_id)
    if body is None or not _type_color_ok(body):
        return ""
    color, known = _classify_color(body.get("color") if "color" in body else None)
    if not known:
        return ""
    return color


def _type_skip_count(doc: dict[str, Any], sidecar: dict[str, Any]) -> int:
    """Invalid type records, unknown colors, dangling assignments. Nodes stay."""
    skipped = 0
    valid_ids: set[str] = set()
    types = sidecar.get("types") if isinstance(sidecar, dict) else None
    if isinstance(types, dict):
        for type_id, entry in types.items():
            if not _type_record_ok(type_id, entry):
                skipped += 1
                continue
            valid_ids.add(str(type_id))
            if isinstance(entry, dict) and not _type_color_ok(entry):
                skipped += 1
    elif types is not None:
        skipped += 1
    live = _node_id_set(doc)
    assignments = sidecar.get("assignments") if isinstance(sidecar, dict) else None
    if isinstance(assignments, dict):
        for node_id, type_id in assignments.items():
            if node_id not in live or not isinstance(type_id, str) or type_id not in valid_ids:
                skipped += 1
    elif assignments is not None:
        skipped += 1
    return skipped


def _explicit_node_color(body: dict[str, Any] | None) -> tuple[bool, str, bool]:
    """(present, color, known). Missing key is not an override."""
    if body is None or "color" not in body:
        return False, "", True
    color, known = _classify_color(body.get("color"))
    return True, color, known


def sidecar_status_note(doc: dict[str, Any], sidecar: dict[str, Any] | None) -> str | None:
    if not isinstance(sidecar, dict):
        return None
    notes: list[str] = []
    version = sidecar.get("bendwright_sidecar")
    if version not in (None, 1):
        notes.append(
            f"sidecar: newer bendwright_sidecar version {version}; applied known fields"
        )
    skipped = _style_skip_count(doc, sidecar)
    if skipped:
        notes.append(
            "sidecar: skipped "
            f"{skipped} entries (unknown color or dash, or dangling key)"
        )
    return _join_notes(*notes)


def load_sidecar(ir_path: Path, doc: dict[str, Any]) -> tuple[dict[str, Any], str | None, bool]:
    """Return (sidecar, note, unreadable). Missing file is an empty v1 sidecar.

    A newer version keeps unknown keys. An unreadable file is NOT replaced.
    """
    path = sidecar_path_for(ir_path)
    if not path.is_file():
        return empty_sidecar(), None, False
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        return (
            empty_sidecar(),
            f"sidecar: could not read {path.name}; left the file untouched",
            True,
        )
    if not isinstance(data, dict):
        return (
            empty_sidecar(),
            f"sidecar: {path.name} is not a JSON object; left the file untouched",
            True,
        )
    stored = copy.deepcopy(data)
    if "bendwright_sidecar" not in stored:
        stored["bendwright_sidecar"] = 1
    renamed = _migrate_type_icons(stored.get("types"))
    note = _join_notes(
        sidecar_status_note(doc, stored),
        _icon_rename_note(renamed),
        _dropped_brand_offer_note(doc),
    )
    return stored, note, False


def _sidecar_has_payload(sidecar: dict[str, Any]) -> bool:
    version = sidecar.get("bendwright_sidecar")
    if version not in (None, 1):
        return True
    for key, value in sidecar.items():
        if key == "bendwright_sidecar":
            continue
        if key in ("edges", "nodes", "types", "assignments", "icons") and isinstance(value, dict) and not value:
            continue
        return True
    return False


def write_sidecar_for(ir_path: Path, sidecar: dict[str, Any], *, unreadable: bool) -> str | None:
    """Atomic replace on Save. Returns a note. Does not raise.

    Empty payload deletes an existing file. An unreadable file is left alone.
    """
    path = sidecar_path_for(ir_path)
    if unreadable:
        return f"sidecar: {path.name} was not overwritten (unreadable)"
    if not isinstance(sidecar, dict):
        return "sidecar write failed: not an object"
    if not _sidecar_has_payload(sidecar):
        if path.is_file():
            try:
                path.unlink()
            except OSError as e:
                return f"sidecar write failed: {e}"
        return None
    payload = copy.deepcopy(sidecar)
    if "bendwright_sidecar" not in payload:
        payload["bendwright_sidecar"] = 1
    _sync_sidecar_icons(payload)
    # Empty type maps are editor defaults. Do not add them to an M28a sidecar.
    for optional in ("types", "assignments", "icons"):
        if isinstance(payload.get(optional), dict) and not payload[optional]:
            payload.pop(optional, None)
    try:
        atomic_write(path, payload, True)
    except OSError as e:
        return f"sidecar write failed: {e}"
    return None


def _css_attr(value: str) -> str:
    return value.replace("\\", "\\\\").replace('"', '\\"')


def _alpha_hex(hex_color: str, alpha: float) -> str:
    body = hex_color[1:] if hex_color.startswith("#") else hex_color
    channel = max(0, min(255, round(alpha * 255)))
    return f"#{body}{channel:02X}"


def _style_miss_note(count: int) -> str:
    return f"archify markup changed; custom styles not applied to {count} items"


def _markup_miss_from_note(note: str | None) -> str | None:
    """The guard sentence, if present, so status can show it without the rest."""
    if not isinstance(note, str):
        return None
    marker = "archify markup changed"
    at = note.find(marker)
    if at < 0:
        return None
    return note[at:]


def _edge_label_text(edge: dict[str, Any]) -> str | None:
    """Value archify writes to data-edge-label. Empty omits the attribute."""
    label = edge.get("label")
    if isinstance(label, str) and label != "":
        return label
    return None


def _idless_label_buckets(doc: dict[str, Any]) -> dict[tuple[str, str, str | None], list[int]]:
    """IR indexes of id-less edges grouped by from, to, and label. IR order."""
    buckets: dict[tuple[str, str, str | None], list[int]] = {}
    edges = doc.get("edges")
    if not isinstance(edges, list):
        return buckets
    for index, edge, _key in iter_edge_style_keys(doc):
        if _edge_id_value(edge):
            continue
        fr = edge.get("from") if isinstance(edge.get("from"), str) else ""
        to = edge.get("to") if isinstance(edge.get("to"), str) else ""
        buckets.setdefault((fr, to, _edge_label_text(edge)), []).append(index)
    return buckets


def _tag_attr(tag: str, name: str) -> str | None:
    match = re.search(rf'\b{re.escape(name)}="([^"]*)"', tag)
    if not match:
        return None
    return match.group(1)


def _iter_open_tags(text: str, tag: str) -> list[tuple[int, int, str]]:
    pattern = re.compile(rf"<{tag}\b[^>]*>", re.IGNORECASE)
    return [(m.start(), m.end(), m.group(0)) for m in pattern.finditer(text)]


def _set_marker_end(tag: str, marker_id: str) -> str:
    attr = str(_OVERLAY_MARKUP["marker_end_attr"])
    value = html_escape(f"url(#{marker_id})", quote=True)
    pattern = re.compile(rf'(\b{re.escape(attr)}=")([^"]*)(")')
    if pattern.search(tag):
        return pattern.sub(lambda m: m.group(1) + value + m.group(3), tag, count=1)
    if tag.endswith("/>"):
        return tag[:-2] + f' {attr}="{value}"/>'
    if tag.endswith(">"):
        return tag[:-1] + f' {attr}="{value}">'
    return tag


def _overlay_node_span(html: str, node_id: str) -> tuple[int, int] | None:
    tag = str(_OVERLAY_MARKUP["node_group_tag"])
    attr = str(_OVERLAY_MARKUP["node_id_attr"])
    open_re = re.compile(
        rf'<{tag}\b(?=[^>]*\b{re.escape(attr)}="{re.escape(node_id)}")[^>]*>',
        re.IGNORECASE,
    )
    token_re = re.compile(rf"</{tag}>|<{tag}\b", re.IGNORECASE)
    match = open_re.search(html)
    if not match:
        return None
    pos = match.end()
    depth = 1
    end: int | None = None
    while pos < len(html):
        token = token_re.search(html, pos)
        if not token:
            return None
        if token.group(0).startswith("</"):
            depth -= 1
            if depth == 0:
                end = token.end()
                break
        else:
            depth += 1
        pos = token.end()
    if end is None:
        return None
    return match.start(), end


def _direct_box_count(group_html: str) -> int:
    group_tag = str(_OVERLAY_MARKUP["node_group_tag"])
    box_tag = str(_OVERLAY_MARKUP["node_box_tag"])
    open_end = group_html.find(">")
    if open_end < 0:
        return 0
    token_re = re.compile(
        rf"</{group_tag}>|<{group_tag}\b|<{box_tag}\b",
        re.IGNORECASE,
    )
    pos = open_end + 1
    depth = 1
    count = 0
    while pos < len(group_html):
        token = token_re.search(group_html, pos)
        if not token:
            break
        word = token.group(0)
        if word.startswith("</"):
            depth -= 1
            if depth == 0:
                break
        elif word.lower().startswith("<" + group_tag.lower()):
            depth += 1
        elif word.lower().startswith("<" + box_tag.lower()) and depth == 1:
            count += 1
        pos = token.end()
    return count


def _edge_selector(target: dict[str, Any]) -> str:
    """Attribute selector. Never data-edge-key. Same rule as _path_matches_edge."""
    markup = _OVERLAY_MARKUP
    parts = [
        f'{markup["edge_tag"]}[{markup["edge_from_attr"]}="{_css_attr(str(target["from"]))}"]',
        f'[{markup["edge_to_attr"]}="{_css_attr(str(target["to"]))}"]',
    ]
    if target["match"] == "id":
        parts.append(f'[{markup["edge_id_attr"]}="{_css_attr(str(target["id"]))}"]')
        return "".join(parts)
    parts.append(f':not([{markup["edge_id_attr"]}])')
    label = target.get("label")
    if isinstance(label, str) and label != "":
        parts.append(f'[{markup["edge_label_attr"]}="{_css_attr(label)}"]')
    else:
        parts.append(f':not([{markup["edge_label_attr"]}])')
    return "".join(parts)


def _decoded_attr(tag: str, name: str) -> str | None:
    raw = _tag_attr(tag, name)
    if raw is None:
        return None
    return html_unescape(raw)


def _path_matches_edge(tag: str, target: dict[str, Any]) -> bool:
    markup = _OVERLAY_MARKUP
    if _decoded_attr(tag, str(markup["edge_from_attr"])) != target["from"]:
        return False
    if _decoded_attr(tag, str(markup["edge_to_attr"])) != target["to"]:
        return False
    tag_id = _decoded_attr(tag, str(markup["edge_id_attr"])) or ""
    if target["match"] == "id":
        return tag_id == target["id"]
    if tag_id:
        return False
    tag_label = _decoded_attr(tag, str(markup["edge_label_attr"]))
    label = target.get("label")
    if not isinstance(label, str) or label == "":
        return tag_label is None
    return tag_label == label


def _node_box_selector(node_id: str) -> str:
    markup = _OVERLAY_MARKUP
    nth = int(markup["node_box_nth"])
    return (
        f'{markup["node_group_tag"]}[{markup["node_id_attr"]}="{_css_attr(node_id)}"]'
        f' > {markup["node_box_tag"]}:nth-of-type({nth})'
    )


def _theme_rule(theme: str, selector: str, body: str) -> str:
    attr = str(_OVERLAY_MARKUP["theme_attr"])
    return f'html[{attr}="{theme}"] {selector} {{ {body} }}'


def _collect_style_targets(
    doc: dict[str, Any], sidecar: dict[str, Any]
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Paintable edges and nodes. Unknown and dangling entries are not included."""
    edges_out: list[dict[str, Any]] = []
    edge_map = sidecar.get("edges") if isinstance(sidecar, dict) else None
    if isinstance(edge_map, dict):
        for index, edge, key in iter_edge_style_keys(doc):
            body = _entry_is_dict(edge_map.get(key))
            if body is None:
                continue
            color, color_ok = _classify_color(body.get("color") if "color" in body else None)
            dash = _classify_dash("dash" in body, body.get("dash") if "dash" in body else None)
            if not color_ok or dash is None:
                continue
            if not color and dash == "solid":
                continue
            fr = edge.get("from") if isinstance(edge.get("from"), str) else ""
            to = edge.get("to") if isinstance(edge.get("to"), str) else ""
            edges_out.append(
                {
                    "index": index,
                    "from": fr,
                    "to": to,
                    "id": _edge_id_value(edge),
                    "label": _edge_label_text(edge),
                    "color": color,
                    "dash": dash,
                    "match": "id",
                    "occurrence": 0,
                    "bucket": 1,
                    "apply": False,
                }
            )
    nodes_out: list[dict[str, Any]] = []
    node_map = sidecar.get("nodes") if isinstance(sidecar, dict) else None
    nodes = doc.get("nodes")
    if isinstance(nodes, list):
        for node in nodes:
            if not isinstance(node, dict) or not isinstance(node.get("id"), str):
                continue
            node_id = node["id"]
            body = None
            if isinstance(node_map, dict):
                body = _entry_is_dict(node_map.get(node_id))
            present, color, color_ok = _explicit_node_color(body)
            if present:
                # Per-node color wins over the type color, including explicit none.
                if not color_ok or not color:
                    continue
                nodes_out.append({"id": node_id, "color": color})
                continue
            inherited = _inherited_type_color(sidecar, node_id)
            if inherited:
                nodes_out.append({"id": node_id, "color": inherited})
    _attach_edge_match(doc, edges_out)
    return edges_out, nodes_out


def _collect_kind_targets(
    doc: dict[str, Any], sidecar: dict[str, Any]
) -> list[dict[str, Any]]:
    """Custom-typed nodes to label. Sidecar only; the user library is not read."""
    found: list[dict[str, Any]] = []
    nodes = doc.get("nodes")
    assignments = sidecar.get("assignments") if isinstance(sidecar, dict) else None
    if not isinstance(nodes, list) or not isinstance(assignments, dict):
        return found
    for node in nodes:
        if not isinstance(node, dict) or not isinstance(node.get("id"), str):
            continue
        node_id = node["id"]
        type_id = assignments.get(node_id)
        body = _assigned_type_body(sidecar, node_id)
        if body is None or not isinstance(type_id, str):
            continue
        label = str(body.get("label") or "").strip()
        if not label:
            continue
        color, _known = _classify_color(body.get("color") if "color" in body else None)
        icon = body.get("icon")
        if not isinstance(icon, str) or icon in ("", "none"):
            icon = ""
        found.append(
            {
                "id": node_id,
                "type_id": type_id,
                "label": label,
                "color": color,
                "icon": icon,
            }
        )
    return found


def _attach_edge_match(doc: dict[str, Any], edges_out: list[dict[str, Any]]) -> None:
    """Fill match/occurrence/bucket. See the _OVERLAY_MARKUP comment."""
    placed: dict[int, tuple[tuple[str, str, str | None], int, int]] = {}
    for key, indexes in _idless_label_buckets(doc).items():
        size = len(indexes)
        for n, index in enumerate(indexes):
            placed[index] = (key, n, size)
    for target in edges_out:
        if target["id"]:
            target["match"] = "id"
            target["label"] = None
            target["occurrence"] = 0
            target["bucket"] = 1
            continue
        found = placed.get(int(target["index"]))
        if found is None:
            target["match"] = "attrs"
            target["bucket"] = 1
            continue
        _key, occurrence, size = found
        target["label"] = _key[2]
        target["occurrence"] = occurrence
        target["bucket"] = size
        target["match"] = "order" if size > 1 else "attrs"


def _same_paint(group: list[dict[str, Any]]) -> bool:
    paints = {(str(item["color"]), str(item["dash"])) for item in group}
    return len(paints) == 1


def _legend_entries(
    edge_targets: list[dict[str, Any]], node_targets: list[dict[str, Any]]
) -> list[tuple[str, str, str]]:
    """Unique (color, dash, label). Node color shares the solid edge combo."""
    combos: set[tuple[str, str]] = set()
    for target in edge_targets:
        dash = "" if target["dash"] == "solid" else str(target["dash"])
        combos.add((str(target["color"]), dash))
    for target in node_targets:
        combos.add((str(target["color"]), ""))
    ordered: list[tuple[str, str, str]] = []
    dash_order = ("", "dashed", "dotted")
    colors = list(_STYLE_COLOR_ORDER) + [""]
    for color in colors:
        for dash in dash_order:
            if (color, dash) not in combos:
                continue
            if color and not dash:
                label = _STYLE_COLORS[color]["label"]
            elif color and dash:
                label = f'{_STYLE_COLORS[color]["label"]} · {dash}'
            else:
                label = dash
            ordered.append((color, dash, label))
    return ordered


def _build_overlay_css(
    edge_targets: list[dict[str, Any]], node_targets: list[dict[str, Any]]
) -> str:
    dark = str(_OVERLAY_MARKUP["theme_dark"])
    light = str(_OVERLAY_MARKUP["theme_light"])
    lines: list[str] = []
    used_colors: list[str] = []
    for target in edge_targets:
        if not target.get("apply"):
            continue
        selector = _edge_selector(target)
        color = str(target["color"])
        dash = str(target["dash"])
        dash_value = _STYLE_DASHES.get(dash)
        base: list[str] = []
        if color:
            ramp = _STYLE_COLORS[color]
            base.append(f'stroke: {ramp["dark"]}')
            lines.append(
                _theme_rule(
                    dark,
                    selector,
                    f'stroke: {ramp["dark"]}; marker-end: url(#{_arrow_marker_id(color, dark)})',
                )
            )
            lines.append(
                _theme_rule(
                    light,
                    selector,
                    f'stroke: {ramp["light"]}; marker-end: url(#{_arrow_marker_id(color, light)})',
                )
            )
            if color not in used_colors:
                used_colors.append(color)
        if dash_value:
            base.append(f"stroke-dasharray: {dash_value}")
        if base:
            lines.append(f'{selector} {{ {"; ".join(base)}; }}')
    for target in node_targets:
        color = str(target["color"])
        ramp = _STYLE_COLORS[color]
        selector = _node_box_selector(str(target["id"]))
        dark_fill = _alpha_hex(ramp["dark"], _NODE_FILL_ALPHA)
        light_fill = _alpha_hex(ramp["light"], _NODE_FILL_ALPHA)
        lines.append(
            _theme_rule(dark, selector, f'stroke: {ramp["dark"]}; fill: {dark_fill}')
        )
        lines.append(
            _theme_rule(light, selector, f'stroke: {ramp["light"]}; fill: {light_fill}')
        )
        lines.append(f'{selector} {{ stroke: {ramp["dark"]}; fill: {dark_fill}; }}')
    legend_id = str(_OVERLAY_MARKUP["legend_id"])
    lines.append(
        f'#{legend_id} {{ font: 12px/1.4 system-ui, sans-serif; margin: 12px 16px; }}'
    )
    lines.append(f'#{legend_id} ul {{ list-style: none; padding: 0; margin: 8px 0 0; }}')
    lines.append(f'#{legend_id} li {{ margin: 2px 0; }}')
    lines.append(
        ".bw-swatch { display: inline-block; width: 12px; height: 12px; "
        "border-radius: 2px; margin-right: 6px; vertical-align: -2px; }"
    )
    lines.append(
        f"#{legend_id} img {{ width: 14px; height: 14px; object-fit: contain; "
        "vertical-align: -2px; margin-right: 4px; }}"
    )
    for name, ramp in _STYLE_COLORS.items():
        swatch = f'.bw-swatch[data-bw-color="{name}"]'
        lines.append(f'{swatch} {{ background: {ramp["dark"]}; }}')
        lines.append(_theme_rule(light, swatch, f'background: {ramp["light"]}'))
        lines.append(_theme_rule(dark, swatch, f'background: {ramp["dark"]}'))
    return "\n".join(lines)


def _arrow_marker_id(color: str, theme: str) -> str:
    return f"bw-arrow-{color}-{theme}"


def _marker_defs(colors: list[str]) -> str:
    """One marker per color per theme. Fill is the theme hex, not a shared dark fill."""
    markup = _OVERLAY_MARKUP
    parts: list[str] = []
    themes = (str(markup["theme_dark"]), str(markup["theme_light"]))
    for color in colors:
        ramp = _STYLE_COLORS[color]
        for theme in themes:
            fill = html_escape(ramp[theme], quote=True)
            parts.append(
                f'<{markup["marker_tag"]} id="{_arrow_marker_id(color, theme)}" '
                f'markerWidth="{markup["marker_width"]}" '
                f'markerHeight="{markup["marker_height"]}" '
                f'refX="{markup["marker_ref_x"]}" refY="{markup["marker_ref_y"]}" '
                f'orient="{markup["marker_orient"]}">'
                f'<{markup["marker_shape_tag"]} points="{markup["marker_points"]}" '
                f'fill="{fill}"/></{markup["marker_tag"]}>'
            )
    return "".join(parts)


def _legend_icon_html(icon: str, sidecar: dict[str, Any] | None = None) -> str:
    """Embedded PNG for gap and user icons so export does not call /brand."""
    if not icon:
        return ""
    brand = _icon_asset(icon, sidecar)
    if brand is None:
        return f'<span class="bw-type-icon">{html_escape(icon)}</span> '
    encoded = base64.b64encode(brand["png"]).decode("ascii")
    return f'<img alt="" src="data:image/png;base64,{encoded}" width="14" height="14">'


def _legend_html(
    entries: list[tuple[str, str, str]],
    type_rows: list[dict[str, Any]],
    sidecar: dict[str, Any] | None = None,
) -> str:
    if not entries and not type_rows:
        return ""
    tag = str(_OVERLAY_MARKUP["legend_tag"])
    legend_id = str(_OVERLAY_MARKUP["legend_id"])
    items: list[str] = []
    for color, _dash, label in entries:
        swatch = ""
        if color:
            swatch = f'<span class="bw-swatch" data-bw-color="{html_escape(color, quote=True)}"></span>'
        items.append(f"<li>{swatch}{html_escape(label)}</li>")
    seen: set[str] = set()
    ordered = sorted(
        type_rows,
        key=lambda row: (str(row.get("label") or "").lower(), str(row.get("type_id") or "")),
    )
    for row in ordered:
        type_id = str(row.get("type_id") or "")
        if not type_id or type_id in seen:
            continue
        seen.add(type_id)
        color = str(row.get("color") or "")
        swatch = ""
        if color in _STYLE_COLORS:
            swatch = (
                f'<span class="bw-swatch" data-bw-color="{html_escape(color, quote=True)}"></span>'
            )
        icon = _legend_icon_html(str(row.get("icon") or ""), sidecar)
        items.append(f"<li>{swatch}{icon}{html_escape(str(row.get('label') or ''))}</li>")
    return (
        f'<{tag} id="{legend_id}" data-bw-style-legend="1">'
        f"<p>{html_escape(_LEGEND_HINT)}</p>"
        f'<ul>{"".join(items)}</ul>'
        f"</{tag}>"
    )


def _set_open_attr(tag: str, attr: str, value: str) -> str:
    safe = html_escape(value, quote=True)
    pattern = re.compile(rf'(\b{re.escape(attr)}=")([^"]*)(")')
    if pattern.search(tag):
        return pattern.sub(lambda m: m.group(1) + safe + m.group(3), tag, count=1)
    if tag.endswith("/>"):
        return tag[:-2] + f' {attr}="{safe}"/>'
    if tag.endswith(">"):
        return tag[:-1] + f' {attr}="{safe}">'
    return tag


def _append_visible_label(value: str, label: str) -> str:
    """Append label unless the last ' · ' token already equals it. Case-sensitive.

    "VM" + VM stays "VM" (not "VM · VM"). A longer last token is not a match.
    """
    if not label:
        return value
    parts = value.split(" · ")
    if parts and parts[-1] == label:
        return value
    return value + f" · {label}"


def _apply_kind_labels(text: str, targets: list[dict[str, Any]]) -> tuple[str, int]:
    """Set data-node-kind-label and append the custom label to title and aria-label.

    Does not change data-node-kind. One miss per node that cannot be fully labeled.
    """
    missed = 0
    kind_attr = str(_OVERLAY_MARKUP["node_kind_label_attr"])
    aria_attr = str(_OVERLAY_MARKUP["node_aria_attr"])
    title_tag = str(_OVERLAY_MARKUP["node_title_tag"])
    title_re = re.compile(
        rf"(<{title_tag}\b[^>]*>)(.*?)(</{title_tag}>)",
        re.IGNORECASE | re.DOTALL,
    )
    for target in targets:
        span = _overlay_node_span(text, str(target["id"]))
        if span is None:
            missed += 1
            continue
        start, end = span
        group = text[start:end]
        open_end = group.find(">")
        if open_end < 0:
            missed += 1
            continue
        label = str(target["label"])
        open_tag = _set_open_attr(group[: open_end + 1], kind_attr, label)
        aria_raw = _tag_attr(open_tag, aria_attr)
        if aria_raw is not None:
            open_tag = _set_open_attr(
                open_tag, aria_attr, _append_visible_label(html_unescape(aria_raw), label)
            )
        rest = group[open_end + 1 :]
        title_match = title_re.search(rest)
        if title_match is not None:
            body = html_unescape(title_match.group(2))
            updated = html_escape(_append_visible_label(body, label), quote=False)
            rest = (
                rest[: title_match.start()]
                + title_match.group(1)
                + updated
                + title_match.group(3)
                + rest[title_match.end() :]
            )
        if aria_raw is None or title_match is None:
            missed += 1
        text = text[:start] + open_tag + rest + text[end:]
    return text, missed


def _insert_style_block(text: str, css: str) -> str:
    style_id = str(_OVERLAY_MARKUP["style_id"])
    block = f'<style id="{style_id}">\n{css}\n</style>'
    matches = list(re.finditer(r"</style>", text, re.IGNORECASE))
    if matches:
        at = matches[-1].end()
        return text[:at] + block + text[at:]
    svg = re.search(r"<svg\b", text, re.IGNORECASE)
    if svg:
        return text[: svg.start()] + block + text[svg.start() :]
    return block + text


def _mark_paintable_edges(edge_targets: list[dict[str, Any]]) -> int:
    """Drop edges whose selector cannot name a single path. Returns miss count.

    A duplicate from/to/label bucket shares one attribute selector. Paint it
    only when every edge in the bucket carries the same color and dash.
    """
    groups: dict[tuple[str, str, str | None], list[dict[str, Any]]] = {}
    for target in edge_targets:
        target["apply"] = True
        if target.get("match") != "order":
            continue
        label = target.get("label")
        if not isinstance(label, str) or label == "":
            label = None
        key = (str(target["from"]), str(target["to"]), label)
        groups.setdefault(key, []).append(target)
    missed = 0
    for group in groups.values():
        bucket = int(group[0]["bucket"])
        if len(group) == bucket and _same_paint(group):
            continue
        for target in group:
            target["apply"] = False
            missed += 1
    return missed


def _apply_style_overlay(
    html: bytes, ir_path: Path, sidecar: dict[str, Any] | None
) -> tuple[bytes, str | None]:
    """Inject preset paint into delivered HTML. Never fails the deliver.

    Does not write the path style attribute, stroke-dashoffset, or !important
    on dasharray, dashoffset, opacity, filter, or stroke-width. The edge-label
    g is not retargeted. marker-end is a path attribute (dark marker); theme
    CSS points it at the light or dark marker.
    """
    loaded = _read_saved_doc(ir_path)
    if loaded is None or not isinstance(sidecar, dict):
        return html, None
    doc = loaded[0]
    status = sidecar_status_note(doc, sidecar)
    edge_targets, node_targets = _collect_style_targets(doc, sidecar)
    kind_targets = _collect_kind_targets(doc, sidecar)
    if not edge_targets and not node_targets and not kind_targets:
        return html, status
    try:
        text = html.decode("utf-8")
    except UnicodeError:
        return html, _join_notes(
            status,
            _style_miss_note(len(edge_targets) + len(node_targets) + len(kind_targets)),
        )

    missed = _mark_paintable_edges(edge_targets)
    path_tag = str(_OVERLAY_MARKUP["edge_tag"])
    paths = _iter_open_tags(text, path_tag)
    replacements: list[tuple[int, int, str]] = []
    fallback_theme = str(_OVERLAY_MARKUP["theme_dark"])
    for target in edge_targets:
        if not target.get("apply"):
            continue
        hits = [item for item in paths if _path_matches_edge(item[2], target)]
        if target.get("match") == "order":
            n = int(target["occurrence"])
            if len(hits) != int(target["bucket"]) or n < 0 or n >= len(hits):
                target["apply"] = False
                missed += 1
                continue
            chosen = hits[n]
        elif len(hits) != 1:
            target["apply"] = False
            missed += 1
            continue
        else:
            chosen = hits[0]
        start, end, tag = chosen
        if target["color"]:
            updated = _set_marker_end(
                tag, _arrow_marker_id(str(target["color"]), fallback_theme)
            )
            # marker-end is an attribute. Never rewrite style (it holds --step).
            if _tag_attr(updated, "style") != _tag_attr(tag, "style"):
                target["apply"] = False
                missed += 1
                continue
            replacements.append((start, end, updated))
        # A dash-only edge matches but does not retarget the arrow.

    css = _build_overlay_css(edge_targets, node_targets)
    if "!important" in css or "stroke-dashoffset" in css:
        return html, _join_notes(
            status,
            _style_miss_note(len(edge_targets) + len(node_targets) + len(kind_targets)),
        )

    colors: list[str] = []
    for target in edge_targets:
        if not target.get("apply"):
            continue
        color = str(target["color"])
        if color and color not in colors:
            colors.append(color)
    markers = _marker_defs(colors)
    for start, end, updated in reversed(replacements):
        text = text[:start] + updated + text[end:]

    box_needed = int(_OVERLAY_MARKUP["node_box_nth"])
    for target in node_targets:
        span = _overlay_node_span(text, str(target["id"]))
        if span is None:
            missed += 1
            continue
        group = text[span[0] : span[1]]
        if _direct_box_count(group) < box_needed:
            missed += 1

    if markers:
        defs = str(_OVERLAY_MARKUP["defs_tag"])
        close = re.search(rf"</{defs}>", text, re.IGNORECASE)
        if close:
            text = text[: close.start()] + markers + text[close.start() :]
        else:
            # Paths were retargeted but no <defs> to hold the markers.
            missed += len(replacements)
    text, kind_missed = _apply_kind_labels(text, kind_targets)
    missed += kind_missed
    text = _insert_style_block(text, css)
    painted_edges = [target for target in edge_targets if target.get("apply")]
    legend = _legend_html(_legend_entries(painted_edges, node_targets), kind_targets, sidecar)
    if legend:
        close_svg = re.search(r"</svg>", text, re.IGNORECASE)
        if close_svg:
            text = text[: close_svg.end()] + legend + text[close_svg.end() :]
        else:
            text += legend
    note = status
    if missed:
        note = _join_notes(note, _style_miss_note(missed))
    return text.encode("utf-8"), note


def _legend_bytes(preview: bytes) -> bytes | None:
    legend_id = str(_OVERLAY_MARKUP["legend_id"]).encode("ascii")
    tag = str(_OVERLAY_MARKUP["legend_tag"]).encode("ascii")
    pattern = re.compile(
        rb"<" + tag + rb"\b[^>]*\bid=\"" + re.escape(legend_id) + rb"\"[^>]*>.*?</" + tag + rb">",
        re.IGNORECASE | re.DOTALL,
    )
    match = pattern.search(preview)
    return match.group(0) if match else None


def _split_edit_body(body: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any] | None, str | None]:
    """Return (ir, sidecar or None, error). Wrapper is {doc, sidecar}; else the body is the IR."""
    if "sidecar" in body and isinstance(body.get("doc"), dict):
        sidecar = body.get("sidecar")
        if sidecar is None:
            return body["doc"], None, None
        if not isinstance(sidecar, dict):
            return body, None, "sidecar must be a JSON object"
        return body["doc"], sidecar, None
    return body, None, None


def _attach_library_icon_blob(entry: dict[str, Any]) -> None:
    """User-icon bytes travel with the library entry. Catalog and gap icons do not.

    Folder bytes win. If that file is gone, keep sidecar bytes, else the blob
    already stored on this entry, so another machine can still render.
    """
    icon = entry.get("icon")
    if (
        not isinstance(icon, str)
        or icon.strip() in ("", "none")
        or icon in _BRANDS
        or icon in _catalog_ids
        or icon in _DROPPED_BRAND_CATALOG
    ):
        entry.pop("icon_blob", None)
        return
    blob = _user_icon_blob(icon)
    if blob is None:
        got = _sidecar_icon_bytes(icon, _sidecar)
        if got is not None:
            raw, digest = got
            blob = {"sha256": digest, "b64": base64.b64encode(raw).decode("ascii")}
    if blob is None:
        old = entry.get("icon_blob")
        if (
            isinstance(old, dict)
            and isinstance(old.get("sha256"), str)
            and isinstance(old.get("b64"), str)
        ):
            entry["icon_blob"] = {"sha256": old["sha256"], "b64": old["b64"]}
            return
        entry.pop("icon_blob", None)
        return
    entry["icon_blob"] = blob


def _remember_sidecar(doc: dict[str, Any], sidecar: dict[str, Any]) -> None:
    global _sidecar, _sidecar_note
    _sidecar = copy.deepcopy(sidecar)
    _sync_sidecar_icons(_sidecar)
    _sidecar_note = _join_notes(
        sidecar_status_note(doc, _sidecar),
        _dropped_brand_offer_note(doc),
    )


def _kind_env_map(doc: dict[str, Any], sidecar: dict[str, Any] | None) -> dict[str, Any] | None:
    """Temp map for ARCHIFY_BENDWRIGHT_KINDS. None when no custom assignment.

    Shape: {nodeId: {label, colorDark, colorLight}}. Colors come from the
    preset table. IR and saved JSON are not modified.
    """
    if not isinstance(sidecar, dict) or not isinstance(doc, dict):
        return None
    targets = _collect_kind_targets(doc, sidecar)
    if not targets:
        return None
    payload: dict[str, Any] = {}
    for target in targets:
        entry: dict[str, str] = {"label": str(target["label"])}
        ramp = _STYLE_COLORS.get(str(target.get("color") or ""))
        if ramp:
            entry["colorDark"] = ramp["dark"]
            entry["colorLight"] = ramp["light"]
        payload[str(target["id"])] = entry
    return payload or None


def _kind_env_map_for_path(ir_path: Path, sidecar: dict[str, Any] | None) -> dict[str, Any] | None:
    loaded = _read_saved_doc(ir_path)
    if loaded is None:
        return None
    return _kind_env_map(loaded[0], sidecar)


_KIND_NOTE_RE = re.compile(r"<!--\s*bendwright:\s*(.*?)\s*-->")


def _compiler_kind_note(stderr: str, html: bytes | None = None) -> str | None:
    """Schema-1 legend skip is a note, not a deliver failure.

    The archify CLI does not forward a successful renderer stderr, so the
    compiler also leaves an HTML comment bendwright can read.
    """
    lines = [
        line.strip()
        for line in (stderr or "").splitlines()
        if line.strip().startswith("[bendwright]")
    ]
    if html:
        try:
            text = html.decode("utf-8")
        except UnicodeError:
            text = ""
        for match in _KIND_NOTE_RE.finditer(text):
            note = match.group(1).strip()
            if note and note not in lines:
                lines.append(note)
    return " ".join(lines) if lines else None


def run_archify(
    archify: str,
    argv: list[str],
    timeout: float = 120.0,
    kind_map: dict[str, Any] | None = None,
) -> tuple[Any, str, str]:
    """Run `node <archify> ...`. Returns (parsed_stdout_json_or_None, stdout, stderr).

    ARCHIFY_BRAND_ALLOW_PRIVATE is set on this subprocess only so loopback
    brand PNGs can be fetched and inlined. ARCHIFY_BENDWRIGHT_KINDS is set
    on this child only when kind_map is non-empty, and the temp file is
    removed before return. os.environ is not modified.
    """
    cmd = ["node", archify, *argv]
    kind_path: str | None = None
    extra: dict[str, str] = {"ARCHIFY_BRAND_ALLOW_PRIVATE": "1"}
    try:
        if kind_map:
            try:
                fd, kind_path = tempfile.mkstemp(prefix=f"{APP}-kinds-", suffix=".json")
                os.close(fd)
                Path(kind_path).write_text(
                    json.dumps(kind_map, ensure_ascii=False), encoding="utf-8"
                )
            except OSError as e:
                return None, "", str(e)
            extra["ARCHIFY_BENDWRIGHT_KINDS"] = kind_path
        try:
            proc = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
                env={**os.environ, **extra},
            )
        except subprocess.TimeoutExpired as e:
            out = (e.stdout or "") if isinstance(e.stdout, str) else ""
            err = (e.stderr or "") if isinstance(e.stderr, str) else f"timeout after {timeout}s"
            return None, out, err
        except OSError as e:
            return None, "", str(e)

        stdout = proc.stdout or ""
        stderr = proc.stderr or ""
        parsed: Any = None
        stripped = stdout.strip()
        if stripped:
            try:
                parsed = json.loads(stripped)
            except json.JSONDecodeError:
                parsed = None
        return parsed, stdout, stderr
    finally:
        if kind_path:
            _unlink_quiet(kind_path)


def format_validate_errors(receipt: dict[str, Any] | None, stderr: str) -> list[str]:
    """Build human-readable errors from a failed validate receipt or non-JSON stdout."""
    if receipt is None or not isinstance(receipt, dict):
        tail = (stderr or "").strip()
        if len(tail) > 800:
            tail = tail[-800:]
        msg = "validate output not JSON"
        if tail:
            msg = f"{msg}: {tail}"
        return [msg]

    errors: list[str] = []
    diags = receipt.get("diagnostics")
    if isinstance(diags, list) and diags:
        first = diags[0]
        if isinstance(first, dict):
            message = first.get("message")
            if message:
                errors.append(str(message))
            fixes = first.get("supportedFixes")
            if isinstance(fixes, list) and fixes:
                errors.append(f"suggested fix: {fixes[0]}")
        errors.append(f"diagnostics: {len(diags)}")
    err = receipt.get("error")
    if isinstance(err, str) and err.strip() and not errors:
        errors.append(err.strip().splitlines()[0])
    if not errors:
        errors.append("validate failed")
    return errors


def deliver_preview(
    archify: str,
    diagram_type: str,
    ir_path: Path,
    sidecar: dict[str, Any] | None = None,
) -> tuple[bytes | None, str | None]:
    """Deliver IR to system-temp HTML; return (html_bytes_or_None, note_or_None)."""
    fd, html_tmp = tempfile.mkstemp(prefix=f"{APP}-prev-", suffix=".html")
    os.close(fd)
    try:
        parsed, _stdout, stderr = run_archify(
            archify,
            ["deliver", diagram_type, str(ir_path), html_tmp, "--json"],
            kind_map=_kind_env_map_for_path(ir_path, sidecar),
        )
        note: str | None = None
        if not isinstance(parsed, dict) or not parsed.get("ok", False):
            if isinstance(parsed, dict):
                diags = parsed.get("diagnostics")
                if isinstance(diags, list) and diags and isinstance(diags[0], dict):
                    note = str(diags[0].get("message") or "deliver failed")
                elif parsed.get("error"):
                    note = str(parsed["error"]).splitlines()[0]
                else:
                    note = "deliver failed"
            else:
                tail = (stderr or "").strip()
                note = "deliver output not JSON" + (f": {tail[-400:]}" if tail else "")
            return None, note

        try:
            html = Path(html_tmp).read_bytes()
        except OSError as e:
            return None, f"deliver ok but could not read HTML: {e}"
        html, brand_note = _apply_brand_display_names(html, ir_path, sidecar)
        html, style_note = _apply_style_overlay(html, ir_path, sidecar)
        return html, _join_notes(brand_note, style_note, _compiler_kind_note(stderr, html))
    finally:
        try:
            os.unlink(html_tmp)
        except OSError:
            pass


def export_html_path(ir_path: Path) -> Path:
    """Sibling .html path: strip .workflow.json else .json, then + .html."""
    name = ir_path.name
    if name.endswith(".workflow.json"):
        stem = name[: -len(".workflow.json")]
    elif name.endswith(".json"):
        stem = name[: -len(".json")]
    else:
        stem = ir_path.stem
    return ir_path.parent / f"{stem}.html"


def format_deliver_errors(receipt: dict[str, Any] | None, stderr: str) -> list[str]:
    """Human-readable errors from a failed deliver --json receipt."""
    if receipt is None or not isinstance(receipt, dict):
        tail = (stderr or "").strip()
        if len(tail) > 800:
            tail = tail[-800:]
        msg = "deliver output not JSON"
        if tail:
            msg = f"{msg}: {tail}"
        return [msg]
    errors: list[str] = []
    diags = receipt.get("diagnostics")
    if isinstance(diags, list) and diags:
        first = diags[0]
        if isinstance(first, dict):
            message = first.get("message")
            if message:
                errors.append(str(message))
        errors.append(f"diagnostics: {len(diags)}")
    err = receipt.get("error")
    if isinstance(err, str) and err.strip() and not errors:
        errors.append(err.strip().splitlines()[0])
    if not errors:
        errors.append("deliver failed")
    return errors


def deliver_to_path(
    archify: str,
    diagram_type: str,
    ir_path: Path,
    out_path: Path,
    sidecar: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Deliver IR to out_path via sibling tmp + os.replace. No lock around subprocess.

    On failure leaves any prior out_path untouched. Returns
    {ok, output, note?} or {ok:false, errors}.
    """
    parent = out_path.parent
    # Archify requires the deliver target to end in .html (rejects bare .tmp).
    fd, tmp_name = tempfile.mkstemp(
        prefix=f".{out_path.stem}.", suffix=".html", dir=str(parent)
    )
    os.close(fd)
    try:
        parsed, _stdout, stderr = run_archify(
            archify,
            ["deliver", diagram_type, str(ir_path), tmp_name, "--json"],
            kind_map=_kind_env_map_for_path(ir_path, sidecar),
        )
        if not isinstance(parsed, dict) or not parsed.get("ok", False):
            return {
                "ok": False,
                "errors": format_deliver_errors(
                    parsed if isinstance(parsed, dict) else None, stderr
                ),
            }
        raw_html = Path(tmp_name).read_bytes()
        raw_html, brand_note = _apply_brand_display_names(raw_html, ir_path, sidecar)
        raw_html, style_note = _apply_style_overlay(raw_html, ir_path, sidecar)
        Path(tmp_name).write_bytes(raw_html)
        os.replace(tmp_name, out_path)
        receipt: dict[str, Any] = {"ok": True, "output": str(out_path)}
        note = parsed.get("note") if isinstance(parsed, dict) else None
        notes = _join_notes(
            note if isinstance(note, str) else None,
            brand_note,
            style_note,
            _compiler_kind_note(stderr, raw_html),
        )
        if notes:
            receipt["note"] = notes
        return receipt
    except OSError as e:
        return {"ok": False, "errors": [f"export write failed: {e}"]}
    finally:
        try:
            os.unlink(tmp_name)
        except OSError:
            pass


def extract_diagram_html(preview: bytes) -> bytes | None:
    """Build a minimal same-origin diagram doc: page <style> blocks + <svg>, no scripts."""
    svg_m = _SVG_RE.search(preview)
    if not svg_m:
        return None
    parts: list[bytes] = [
        b"<!DOCTYPE html>\n<html><head><meta charset=\"utf-8\">\n",
    ]
    parts.extend(_STYLE_BLOCK_RE.findall(preview))
    parts.append(b"\n</head><body style=\"margin:0;background:#0b0f14;\">\n")
    parts.append(svg_m.group(0))
    legend = _legend_bytes(preview)
    if legend:
        parts.append(b"\n")
        parts.append(legend)
    parts.append(b"\n</body></html>\n")
    return b"".join(parts)


def set_preview_html(html: bytes | None) -> None:
    """Update in-memory preview and re-extract the cached diagram fragment."""
    global _preview_html, _diagram_html
    _preview_html = html
    _diagram_html = extract_diagram_html(html) if html else None


def fetch_layout(
    archify: str,
    diagram_type: str,
    ir_path: Path,
    sidecar: dict[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, str]:
    """Run validate --layout-json; parse stdout JSON only (stderr tail on failure)."""
    parsed, stdout, stderr = run_archify(
        archify,
        ["validate", diagram_type, str(ir_path), "--layout-json"],
        kind_map=_kind_env_map_for_path(ir_path, sidecar),
    )
    if isinstance(parsed, dict) and (
        "columns" in parsed or "viewBox" in parsed or "nodes" in parsed
    ):
        return parsed, ""
    tail = (stderr or stdout or "").strip()
    if len(tail) > 800:
        tail = tail[-800:]
    return None, tail or "layout-json stdout was not JSON"


def validate_candidate(
    archify: str, diagram_type: str, doc: dict[str, Any], trailing_newline: bool
) -> tuple[bool, list[str]]:
    """Write candidate to system temp, run validate --json (no --quality)."""
    tmp_name = _archify_temp_json(doc, trailing_newline)
    try:
        return _validate_temp_path(archify, diagram_type, tmp_name)
    finally:
        _unlink_quiet(tmp_name)


def _validate_temp_path(
    archify: str, diagram_type: str, tmp_name: str
) -> tuple[bool, list[str]]:
    """Run validate --json against an existing temp IR path."""
    parsed, _stdout, stderr = run_archify(
        archify,
        ["validate", diagram_type, tmp_name, "--json"],
    )
    if not isinstance(parsed, dict):
        return False, format_validate_errors(None, stderr)
    if parsed.get("ok") is True:
        return True, []
    return False, format_validate_errors(parsed, stderr)


def preview_candidate(
    archify: str,
    diagram_type: str,
    doc: dict[str, Any],
    trailing_newline: bool,
    sidecar: dict[str, Any] | None = None,
) -> tuple[bool, list[str], bytes | None, str | None, dict[str, Any] | None]:
    """Validate + deliver + layout-json from a temp candidate (never touches the real file).

    Returns (ok, errors, html_or_None, note_or_None, layout_or_None).
    """
    tmp_name = _archify_temp_json(doc, trailing_newline, sidecar)
    try:
        ok_v, v_errors = _validate_temp_path(archify, diagram_type, tmp_name)
        if not ok_v:
            return False, v_errors, None, None, None
        html, note = deliver_preview(archify, diagram_type, Path(tmp_name), sidecar)
        layout, layout_err = fetch_layout(
            archify, diagram_type, Path(tmp_name), sidecar
        )
        if layout is None:
            note = _join_notes(note, layout_err or "layout-json failed")
        return True, [], html, note, layout
    finally:
        _unlink_quiet(tmp_name)


def deliver_preview_doc(
    archify: str,
    diagram_type: str,
    doc: dict[str, Any],
    trailing_newline: bool,
    sidecar: dict[str, Any] | None = None,
) -> tuple[bytes | None, str | None]:
    """Deliver a rewritten temp copy. Does not read or write the real IR file."""
    tmp_name = _archify_temp_json(doc, trailing_newline, sidecar)
    try:
        return deliver_preview(archify, diagram_type, Path(tmp_name), sidecar)
    finally:
        _unlink_quiet(tmp_name)


def deliver_saved_file(
    archify: str,
    diagram_type: str,
    ir_path: Path,
    out_path: Path | None = None,
    sidecar: dict[str, Any] | None = None,
) -> tuple[bytes | None, str | None] | dict[str, Any]:
    """Render the saved file through a rewritten temp, never the real path.

    out_path is None -> preview bytes (html, note). Otherwise the export receipt.
    """
    loaded = _read_saved_doc(ir_path)
    if loaded is None:
        if out_path is None:
            return None, "could not read saved diagram for preview"
        return {"ok": False, "errors": ["could not read saved diagram for export"]}
    doc, trailing = loaded
    tmp_name = _archify_temp_json(doc, trailing, sidecar)
    try:
        if out_path is None:
            return deliver_preview(archify, diagram_type, Path(tmp_name), sidecar)
        return deliver_to_path(archify, diagram_type, Path(tmp_name), out_path, sidecar)
    finally:
        _unlink_quiet(tmp_name)


# ---------------------------------------------------------------------------
# HTTP handler
# ---------------------------------------------------------------------------
class Handler(BaseHTTPRequestHandler):
    server_version = f"{APP}/1"

    def log_message(self, fmt: str, *args: Any) -> None:
        sys.stderr.write(f"[{APP}] " + (fmt % args) + "\n")

    def _send(self, code: int, body: bytes, content_type: str) -> None:
        self.send_response(code)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

    def _send_json(self, code: int, obj: Any) -> None:
        data = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self._send(code, data, "application/json; charset=utf-8")

    def _read_json_body(self) -> tuple[Any | None, str | None]:
        length = int(self.headers.get("Content-Length") or "0")
        raw = self.rfile.read(length) if length else b""
        try:
            return json.loads(raw.decode("utf-8")), None
        except (UnicodeDecodeError, json.JSONDecodeError) as e:
            return None, f"invalid JSON body: {e}"

    def _handle_alive(self) -> None:
        """SSE presence. Held open while the tab exists; not an inflight request."""
        global _alive, _alive_seen, _last_zero_ts
        self.close_connection = True
        try:
            self.connection.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        except OSError:
            pass
        try:
            self.send_response(200)
            self.send_header("Content-Type", "text/event-stream")
            self.send_header("Cache-Control", "no-cache")
            self.send_header("Connection", "close")
            self.end_headers()
        except (
            BrokenPipeError,
            ConnectionResetError,
            ConnectionAbortedError,
            TimeoutError,
            OSError,
        ):
            return
        with _alive_lock:
            _alive += 1
            _alive_seen = True
        try:
            # Comment first so EventSource opens before the first sleep. No retry: field.
            while True:
                self.wfile.write(b":\n\n")
                self.wfile.flush()
                time.sleep(ALIVE_KEEPALIVE_S)
        except (
            BrokenPipeError,
            ConnectionResetError,
            ConnectionAbortedError,
            TimeoutError,
            OSError,
        ):
            return
        finally:
            with _alive_lock:
                _alive -= 1
                if _alive == 0:
                    _last_zero_ts = time.monotonic()

    def do_GET(self) -> None:  # noqa: N802
        path = urlparse(self.path).path
        if path == "/api/alive":
            self._handle_alive()
            return
        _begin_request()
        try:
            if path == "/":
                html = SPA_HTML.encode("utf-8")
                self._send(200, html, "text/html; charset=utf-8")
                return
            if path in ("/favicon.svg", "/favicon.ico"):
                # .ico would 404. Same mark as SVG so the tab icon still resolves.
                self._send(200, _FAVICON_SVG, "image/svg+xml")
                return
            if path == "/preview":
                with _state_lock:
                    body = _preview_html
                if body is None:
                    self._send_json(
                        200,
                        {
                            "ok": False,
                            "error": "no preview available (archify absent or deliver not yet run)",
                        },
                    )
                    return
                self._send(200, body, "text/html; charset=utf-8")
                return
            if path == "/api/diagram":
                with _state_lock:
                    body = _diagram_html
                    archify = _archify_path
                if archify is None:
                    self._send_json(404, {"archify": False})
                    return
                if body is None:
                    self._send_json(
                        404,
                        {"ok": False, "error": "no diagram fragment (deliver not yet run)"},
                    )
                    return
                self._send(200, body, "text/html; charset=utf-8")
                return
            if path == "/api/layout":
                # Layout from in-memory _doc (may differ from disk until Save).
                with _state_lock:
                    archify = _archify_path
                    dtype = _diagram_type
                    doc = _doc
                    trailing = _had_trailing_newline
                    sidecar = copy.deepcopy(_sidecar)
                if archify is None or not isinstance(doc, dict) or not doc:
                    self._send_json(404, {"archify": False})
                    return
                tmp_name = _archify_temp_json(doc, trailing, sidecar)
                try:
                    layout, err = fetch_layout(archify, dtype, Path(tmp_name), sidecar)
                finally:
                    _unlink_quiet(tmp_name)
                if layout is None:
                    self._send_json(
                        200,
                        {"ok": False, "error": err or "layout-json failed"},
                    )
                    return
                self._send_json(200, layout)
                return
            brand_match = _BRAND_PATH_RE.match(path)
            if brand_match:
                with _state_lock:
                    sidecar = copy.deepcopy(_sidecar)
                icon = _icon_asset(brand_match.group(1), sidecar)
                if icon is None or not isinstance(icon.get("png"), (bytes, bytearray)):
                    self._send(404, b"unknown brand", "text/plain; charset=utf-8")
                    return
                self._send(200, bytes(icon["png"]), "image/png")
                return
            if path == "/api/brands":
                self._send_json(200, brands_api_payload())
                return
            if path == "/api/catalog":
                self._send_json(200, catalog_api_payload())
                return
            if path == "/api/type-library":
                lib, note = load_type_library()
                payload: dict[str, Any] = {"ok": True, "library": lib}
                if note:
                    payload["note"] = note
                self._send_json(200, payload)
                return
            if path == "/api/state":
                with _state_lock:
                    payload = state_payload()
                self._send_json(200, payload)
                return
            self._send_json(404, {"ok": False, "error": "not found"})
        finally:
            _end_request()

    def do_POST(self) -> None:  # noqa: N802
        global _doc, _file_path, _diagram_type, _had_trailing_newline, _sidecar_unreadable
        _begin_request()
        try:
            path = urlparse(self.path).path
            if path == "/api/pick":
                self._handle_pick()
                return
            if path == "/api/new":
                self._handle_new()
                return
            if path == "/api/brands/rescan":
                self._handle_brand_rescan()
                return
            if path == "/api/open":
                self._handle_open()
                return
            if path == "/api/preview":
                self._handle_preview()
                return
            if path == "/api/export":
                self._handle_export()
                return
            if path == "/api/type-library":
                self._handle_type_library_save()
                return
            if path != "/api/save":
                self._send_json(404, {"ok": False, "error": "not found"})
                return

            body, err = self._read_json_body()
            if err is not None:
                self._send_json(
                    200,
                    {"ok": False, "saved": False, "errors": [err]},
                )
                return

            if not isinstance(body, dict):
                self._send_json(
                    200,
                    {"ok": False, "saved": False, "errors": ["body must be a JSON object"]},
                )
                return
            candidate, sidecar_in, split_err = _split_edit_body(body)
            if split_err:
                self._send_json(
                    200, {"ok": False, "saved": False, "errors": [split_err]}
                )
                return

            errors = structural_check(candidate)
            if errors:
                self._send_json(200, {"ok": False, "saved": False, "errors": errors})
                return

            with _state_lock:
                archify = _archify_path
                trailing = _had_trailing_newline
                dtype = _diagram_type
                target = _file_path

            adopting = False
            if target is None:
                chosen, path_err = _workflow_save_path(body.get("path"))
                if chosen is None:
                    self._send_json(
                        200,
                        {
                            "ok": False,
                            "saved": False,
                            "errors": [path_err or "no file open"],
                        },
                    )
                    return
                target = chosen
                adopting = True
                trailing = True
                inferred = candidate.get("diagram_type")
                if isinstance(inferred, str) and inferred.strip():
                    dtype = inferred.strip()

            if archify:
                ok_v, v_errors = validate_candidate(archify, dtype, candidate, trailing)
                if not ok_v:
                    self._send_json(200, {"ok": False, "saved": False, "errors": v_errors})
                    return

            with _state_lock:
                if not adopting and _file_path is None:
                    self._send_json(
                        200,
                        {"ok": False, "saved": False, "errors": ["no file open"]},
                    )
                    return
                on_disk = _read_saved_doc(target)
                ir_same = on_disk is not None and on_disk[0] == candidate
                # Style-only save must not rewrite the workflow JSON.
                if not ir_same:
                    try:
                        atomic_write(target, candidate, trailing)
                    except OSError as e:
                        self._send_json(
                            200,
                            {"ok": False, "saved": False, "errors": [f"write failed: {e}"]},
                        )
                        return
                if adopting:
                    _file_path = target
                    _diagram_type = dtype
                    _had_trailing_newline = True
                    _sidecar_unreadable = False
                _doc = candidate
                if sidecar_in is not None:
                    sc = copy.deepcopy(sidecar_in)
                else:
                    sc = copy.deepcopy(_sidecar)
                _remember_sidecar(candidate, sc)
                unreadable = _sidecar_unreadable

            sc_note = write_sidecar_for(target, sc, unreadable=unreadable)
            sc_blocked = bool(sc_note) and (
                str(sc_note).startswith("sidecar write failed")
                or "not overwritten" in str(sc_note)
            )
            if sc_blocked and ir_same:
                self._send_json(
                    200, {"ok": False, "saved": False, "errors": [sc_note]}
                )
                return

            receipt: dict[str, Any] = {
                "ok": True,
                "saved": True,
                "structural": True,
                "file": str(target),
            }
            if archify:
                # Render the just-saved file via a rewritten temp. atomic_write
                # above kept the loopback URLs the user authored.
                rendered = deliver_saved_file(archify, dtype, target, None, sc)
                html, note = rendered if isinstance(rendered, tuple) else (None, "preview failed")
                with _state_lock:
                    if html is not None:
                        set_preview_html(html)
                note = _join_notes(sc_note, note)
                if note:
                    receipt["note"] = note
                else:
                    receipt["preview"] = True
            elif sc_note:
                receipt["note"] = sc_note

            self._send_json(200, receipt)
        finally:
            _end_request()

    def _handle_export(self) -> None:
        """Ensure-saved-then-export sibling .html (M19). Lock off archify subprocess."""
        global _doc

        with _state_lock:
            if _file_path is None:
                self._send_json(200, {"ok": False, "errors": ["no file open"]})
                return
            if _archify_path is None:
                self._send_json(
                    200,
                    {
                        "ok": False,
                        "errors": ["archify not available; cannot render HTML"],
                    },
                )
                return
            archify = _archify_path
            trailing = _had_trailing_newline
            dtype = _diagram_type
            target = _file_path

        length = int(self.headers.get("Content-Length") or "0")
        raw = self.rfile.read(length) if length else b""
        # Dirty path: client sends the IR doc; clean path: empty / {} -> deliver from disk.
        stripped = raw.strip()
        sc: dict[str, Any] | None = None
        if stripped and stripped != b"{}":
            try:
                body = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as e:
                self._send_json(
                    200, {"ok": False, "errors": [f"invalid JSON body: {e}"]}
                )
                return
            if not isinstance(body, dict):
                self._send_json(
                    200, {"ok": False, "errors": ["body must be a JSON object"]}
                )
                return
            candidate, sidecar_in, split_err = _split_edit_body(body)
            if split_err:
                self._send_json(200, {"ok": False, "errors": [split_err]})
                return
            errors = structural_check(candidate)
            if errors:
                self._send_json(200, {"ok": False, "errors": errors})
                return
            ok_v, v_errors = validate_candidate(archify, dtype, candidate, trailing)
            if not ok_v:
                self._send_json(200, {"ok": False, "errors": v_errors})
                return
            with _state_lock:
                if _file_path is None:
                    self._send_json(200, {"ok": False, "errors": ["no file open"]})
                    return
                on_disk = _read_saved_doc(target)
                ir_same = on_disk is not None and on_disk[0] == candidate
                if not ir_same:
                    try:
                        atomic_write(target, candidate, trailing)
                    except OSError as e:
                        self._send_json(
                            200, {"ok": False, "errors": [f"write failed: {e}"]}
                        )
                        return
                _doc = candidate
                if sidecar_in is not None:
                    sc = copy.deepcopy(sidecar_in)
                else:
                    sc = copy.deepcopy(_sidecar)
                _remember_sidecar(candidate, sc)
                unreadable = _sidecar_unreadable
            sc_note = write_sidecar_for(target, sc, unreadable=unreadable)
            sc_blocked = bool(sc_note) and (
                str(sc_note).startswith("sidecar write failed")
                or "not overwritten" in str(sc_note)
            )
            if sc_blocked and ir_same:
                self._send_json(200, {"ok": False, "errors": [sc_note]})
                return
        else:
            with _state_lock:
                sc = copy.deepcopy(_sidecar)
            sc_note = None

        out_path = export_html_path(target)
        # Lock OFF during deliver (same as save/preview). Render a rewritten
        # temp so loopback brand URLs resolve; the saved JSON is not rewritten.
        receipt = deliver_saved_file(archify, dtype, target, out_path, sc)
        if not isinstance(receipt, dict):
            receipt = {"ok": False, "errors": ["export failed"]}
        elif sc_note and receipt.get("ok"):
            receipt["note"] = _join_notes(
                sc_note, receipt.get("note") if isinstance(receipt.get("note"), str) else None
            )
        self._send_json(200, receipt)

    def _handle_preview(self) -> None:
        """Validate + deliver from a temp candidate; never write the real file (M13).

        An unsaved new diagram has no path. The in-memory doc is enough.
        """
        global _doc

        body, err = self._read_json_body()
        if err is not None:
            self._send_json(
                200,
                {"ok": False, "preview": False, "saved": False, "errors": [err]},
            )
            return

        if not isinstance(body, dict):
            self._send_json(
                200,
                {
                    "ok": False,
                    "preview": False,
                    "saved": False,
                    "errors": ["body must be a JSON object"],
                },
            )
            return
        candidate, sidecar_in, split_err = _split_edit_body(body)
        if split_err:
            self._send_json(
                200,
                {"ok": False, "preview": False, "saved": False, "errors": [split_err]},
            )
            return

        errors = structural_check(candidate)
        if errors:
            self._send_json(
                200,
                {"ok": False, "preview": False, "saved": False, "errors": errors},
            )
            return

        with _state_lock:
            archify = _archify_path
            trailing = _had_trailing_newline
            dtype = _diagram_type
            if sidecar_in is not None:
                sc = copy.deepcopy(sidecar_in)
            else:
                sc = copy.deepcopy(_sidecar)

        if not archify:
            with _state_lock:
                _doc = candidate
                _remember_sidecar(candidate, sc)
            self._send_json(
                200,
                {
                    "ok": True,
                    "preview": True,
                    "saved": False,
                    "structural": True,
                },
            )
            return

        ok_p, v_errors, html, note, layout = preview_candidate(
            archify, dtype, candidate, trailing, sc
        )
        if not ok_p:
            self._send_json(
                200,
                {
                    "ok": False,
                    "preview": False,
                    "saved": False,
                    "errors": v_errors,
                },
            )
            return

        with _state_lock:
            _doc = candidate
            _remember_sidecar(candidate, sc)
            if html is not None:
                set_preview_html(html)

        receipt: dict[str, Any] = {
            "ok": True,
            "preview": True,
            "saved": False,
            "structural": True,
        }
        if note:
            receipt["note"] = note
        if layout is not None:
            receipt["layout"] = layout
        self._send_json(200, receipt)

    def _handle_type_library_save(self) -> None:
        """Upsert one type into the user library. Does not write the diagram."""
        body, err = self._read_json_body()
        if err is not None:
            self._send_json(200, {"ok": False, "error": err})
            return
        if not isinstance(body, dict):
            self._send_json(200, {"ok": False, "error": "body must be a JSON object"})
            return
        raw = body.get("type") if isinstance(body.get("type"), dict) else body
        if not isinstance(raw, dict):
            self._send_json(200, {"ok": False, "error": "type must be an object"})
            return
        lib, note = save_type_in_library(raw)
        if lib is None:
            self._send_json(200, {"ok": False, "error": note or "type library write failed"})
            return
        payload: dict[str, Any] = {"ok": True, "library": lib}
        if note:
            payload["note"] = note
        self._send_json(200, payload)

    def _handle_pick(self) -> None:
        """Native OS dialog via tkinter subprocess (M12). mode=save asks where to write."""
        mode = "open"
        length = int(self.headers.get("Content-Length") or "0")
        if length:
            body, err = self._read_json_body()
            if err is None and isinstance(body, dict) and body.get("mode") == "save":
                mode = "save"
        with _state_lock:
            current = _file_path
        if current is not None:
            initial_dir = str(current.parent)
        else:
            initial_dir = str(Path.cwd())
        try:
            if mode == "save":
                result = native_save_path(initial_dir)
            else:
                result = native_pick_path(initial_dir)
        except Exception:
            result = {"ok": False, "error": "native picker unavailable"}
        self._send_json(200, result)

    def _handle_new(self) -> None:
        """Replace the session with blank_workflow. No path. Does not write a file."""
        global _file_path, _diagram_type, _doc, _had_trailing_newline
        global _sidecar, _sidecar_note, _sidecar_unreadable
        doc = blank_workflow()
        sc = empty_sidecar()
        with _state_lock:
            _file_path = None
            _diagram_type = "workflow"
            _doc = doc
            _had_trailing_newline = True
            _sidecar = sc
            _sidecar_note = None
            _sidecar_unreadable = False
            archify = _archify_path
            set_preview_html(None)
        if archify:
            rendered = deliver_preview_doc(archify, "workflow", doc, True, sc)
            html, note = rendered if isinstance(rendered, tuple) else (None, "preview failed")
            with _state_lock:
                if isinstance(note, str) and note.strip():
                    _sidecar_note = note
                if html is not None:
                    set_preview_html(html)
        with _state_lock:
            payload = state_payload()
        payload["ok"] = True
        self._send_json(200, payload)

    def _handle_brand_rescan(self) -> None:
        """Rescan catalog.json and bendwright-data/icons. Does not raise."""
        with _state_lock:
            archify = _archify_path
        try:
            load_archify_catalog(archify)
        except Exception:
            pass
        note = scan_user_icons()
        payload: dict[str, Any] = {
            "ok": True,
            "brands": brands_api_payload(),
            "catalog": list(_catalog_marks),
            "catalog_ok": bool(_catalog_marks),
        }
        notes = [item for item in (_catalog_note, note) if item]
        if notes:
            payload["note"] = "\n".join(notes)
        self._send_json(200, payload)

    def _handle_open(self) -> None:
        """Switch the active diagram file (M10). Keeps current file on any failure."""
        global _file_path, _diagram_type, _doc, _had_trailing_newline
        global _sidecar, _sidecar_note, _sidecar_unreadable

        body, err = self._read_json_body()
        if err is not None:
            self._send_json(400, {"ok": False, "error": err})
            return
        if not isinstance(body, dict):
            self._send_json(400, {"ok": False, "error": "body must be a JSON object"})
            return
        raw_path = body.get("path")
        if not isinstance(raw_path, str) or not raw_path.strip():
            self._send_json(400, {"ok": False, "error": "path is required"})
            return
        try:
            target = Path(raw_path).resolve()
        except (OSError, RuntimeError) as e:
            self._send_json(400, {"ok": False, "error": f"bad path: {e}"})
            return
        if not target.is_file():
            self._send_json(400, {"ok": False, "error": f"file not found: {target}"})
            return
        try:
            raw_text = target.read_text(encoding="utf-8")
        except OSError as e:
            self._send_json(400, {"ok": False, "error": f"cannot read file: {e}"})
            return
        trailing = raw_text.endswith("\n")
        try:
            doc = json.loads(raw_text)
        except json.JSONDecodeError as e:
            self._send_json(400, {"ok": False, "error": f"invalid JSON: {e}"})
            return
        if not isinstance(doc, dict):
            self._send_json(400, {"ok": False, "error": "IR root must be a JSON object"})
            return
        dtype = doc.get("diagram_type")
        if not isinstance(dtype, str) or not dtype.strip():
            self._send_json(400, {"ok": False, "error": "missing diagram_type"})
            return
        if dtype != "workflow":
            self._send_json(
                400,
                {
                    "ok": False,
                    "error": f"{dtype} diagrams are not supported yet - workflow only",
                },
            )
            return

        sc, sc_note, sc_bad = load_sidecar(target, doc)
        with _state_lock:
            archify = _archify_path
            _file_path = target
            _diagram_type = dtype
            _doc = doc
            _had_trailing_newline = trailing
            _sidecar = sc
            _sidecar_note = sc_note
            _sidecar_unreadable = sc_bad
            set_preview_html(None)

        if archify:
            rendered = deliver_saved_file(archify, dtype, target, None, sc)
            html = rendered[0] if isinstance(rendered, tuple) else None
            deliver_note = rendered[1] if isinstance(rendered, tuple) else None
            miss = _markup_miss_from_note(deliver_note if isinstance(deliver_note, str) else None)
            with _state_lock:
                if miss:
                    _sidecar_note = _join_notes(_sidecar_note, miss)
                if html is not None:
                    set_preview_html(html)
                else:
                    set_preview_html(None)

        with _state_lock:
            payload = state_payload()
        self._send_json(200, payload)


# Mark geometry from docs/img/bendwright.svg (CC0). Inlined; no file read.
# Header uses currentColor. Favicon is #1B2A38 on a transparent background.
_MARK_SVG_BODY = (
    '<path fill="none" stroke="currentColor" stroke-width="56" '
    'stroke-linecap="butt" stroke-linejoin="miter" '
    'd="M 220 260 H 620 V 764 H 804"/>'
    '<circle cx="220" cy="260" r="78"/>'
    '<circle cx="620" cy="512" r="78"/>'
    '<circle cx="804" cy="764" r="78"/>'
)


def _mark_svg(paint: str, *, decorative: bool) -> str:
    hidden = ' aria-hidden="true" focusable="false"' if decorative else ""
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024"{hidden}>'
        f'<g fill="{paint}" color="{paint}">'
        f"{_MARK_SVG_BODY}"
        "</g></svg>"
    )


_FAVICON_SVG = _mark_svg("#1B2A38", decorative=False).encode("utf-8")
_HEADER_MARK_SVG = _mark_svg("currentColor", decorative=True)


