def _hunk_set_sha(specs: tuple[dict[str, Any], ...]) -> str:
    payload = [
        {"path": spec["path"], "anchors": spec["anchors"]}
        for spec in specs
    ]
    raw = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def _read_patch_state() -> dict[str, Any]:
    path = archify_patch_state_path()
    try:
        data = json.loads(path.read_bytes().decode("utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        return {"hunks": {}}
    if not isinstance(data, dict):
        return {"hunks": {}}
    if not isinstance(data.get("hunks"), dict):
        data["hunks"] = {}
    return data


def _write_bytes_atomic(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=f".{path.name}.", dir=str(path.parent))
    os.close(fd)
    tmp_path = Path(tmp)
    try:
        tmp_path.write_bytes(data)
        os.replace(tmp_path, path)
    finally:
        if tmp_path.exists():
            _unlink_quiet(tmp_path)


def _write_patch_state(data: dict[str, Any]) -> None:
    raw = json.dumps(data, indent=2, ensure_ascii=False).encode("utf-8") + b"\n"
    _write_bytes_atomic(archify_patch_state_path(), raw)


def _sha_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _dir_writable(directory: Path) -> bool:
    """Create-and-delete probe. False on EACCES or a read-only tree."""
    try:
        directory.mkdir(parents=True, exist_ok=True)
        fd, probe = tempfile.mkstemp(prefix=".bw-write-", dir=str(directory))
        os.close(fd)
        os.unlink(probe)
        return True
    except OSError:
        return False


def _backup_path(path: Path) -> Path:
    return path.parent / f"{path.name}{_ARCHIFY_PATCH_BACKUP_SUFFIX}"


def _replace_anchors(
    text: str, anchors: tuple[tuple[str, str], ...]
) -> tuple[str | None, str | None]:
    """Apply every anchor once. Counts are taken on the original text."""
    for index, (old, new) in enumerate(anchors):
        count = text.count(old)
        if count != 1:
            return None, f"anchor {index} matched {count} times"
        if old == new:
            return None, f"anchor {index} is a no-op"
    out = text
    for old, new in anchors:
        out = out.replace(old, new, 1)
    return out, None


def _hash_map(root: Path, rels: tuple[str, ...]) -> dict[str, str] | None:
    found: dict[str, str] = {}
    for rel in rels:
        path = root / rel
        try:
            found[rel] = _sha_bytes(path.read_bytes())
        except OSError:
            return None
    return found


def _record_patch_failure(
    hunk_sha: str,
    root: Path,
    version: str | None,
    current: dict[str, str],
    note: str,
) -> None:
    """Remember this file-hash set so startup does not retry until it changes."""
    try:
        state = _read_patch_state()
        hunks = state.setdefault("hunks", {})
        record = hunks.get(hunk_sha)
        if not isinstance(record, dict):
            record = {}
        record["root"] = str(root)
        record["archify_version"] = version
        record["failure_hashes"] = current
        record["failure_note"] = note
        hunks[hunk_sha] = record
        _write_patch_state(state)
    except OSError:
        return


def _smoke_kind_patch(archify_mjs: str) -> str | None:
    """None when the schema-2 fixture shows the label. Otherwise a short reason.

    Requires data-node-kind-label, the passport/finder/lens label path, and
    one in-drawing legend row. Does not go through run_archify.
    """
    if not shutil.which("node"):
        return "node not on PATH"
    doc = {
        "schema_version": 2,
        "diagram_type": "workflow",
        "meta": {"title": "Bendwright kind smoke", "animation": "none"},
        "lanes": [{"id": "lane", "label": "Lane"}],
        "nodes": [
            {
                "id": "vm",
                "lane": "lane",
                "col": 0,
                "type": "backend",
                "label": "Guest",
            }
        ],
        "edges": [],
    }
    kind_map = {
        "vm": {
            "label": _SMOKE_KIND_LABEL,
            "colorDark": "#6CB4F5",
            "colorLight": "#0072B2",
        }
    }
    fd, fixture = tempfile.mkstemp(prefix=f"{APP}-smoke-", suffix=".json")
    os.close(fd)
    fd, html_path = tempfile.mkstemp(prefix=f"{APP}-smoke-", suffix=".html")
    os.close(fd)
    fd, map_path = tempfile.mkstemp(prefix=f"{APP}-kinds-", suffix=".json")
    os.close(fd)
    try:
        Path(fixture).write_text(json.dumps(doc), encoding="utf-8")
        Path(map_path).write_text(json.dumps(kind_map), encoding="utf-8")
        try:
            proc = subprocess.run(
                ["node", archify_mjs, "deliver", "workflow", fixture, html_path, "--json"],
                capture_output=True,
                text=True,
                timeout=120,
                check=False,
                env={
                    **os.environ,
                    "ARCHIFY_BENDWRIGHT_KINDS": map_path,
                    "ARCHIFY_BRAND_ALLOW_PRIVATE": "1",
                },
            )
        except (OSError, subprocess.TimeoutExpired) as e:
            return f"deliver failed: {e}"
        stdout = proc.stdout or ""
        stderr = proc.stderr or ""
        try:
            parsed = json.loads(stdout.strip()) if stdout.strip() else None
        except json.JSONDecodeError:
            parsed = None
        if not isinstance(parsed, dict) or not parsed.get("ok"):
            tail = (stderr or stdout).strip().splitlines()
            detail = tail[-1][:240] if tail else "deliver failed"
            return f"deliver failed: {detail}"
        try:
            html = Path(html_path).read_text(encoding="utf-8")
        except (OSError, UnicodeError) as e:
            return f"could not read smoke html: {e}"
        label = _SMOKE_KIND_LABEL
        if html.count(f'data-node-kind-label="{label}"') < 1:
            return "missing data-node-kind-label"
        if 'data-node-kind="backend"' not in html:
            return "base data-node-kind missing"
        if html.count(f'data-legend-kind="{label}"') != 1:
            return f"expected one {label} legend row"
        if f'data-legend-label="{label}"' not in html:
            return "legend label is not the raw label"
        if "bw-kind-swatch" not in html or "#6CB4F5" not in html or "#0072B2" not in html:
            return "theme swatch missing"
        passport = (
            "node.getAttribute('data-node-kind-label') || "
            "viewerKindLabel(node.getAttribute('data-node-kind') || 'node')"
        )
        if passport not in html:
            return "passport does not prefer the label attr"
        finder = (
            "function semanticType(node) {\n"
            "        var labeled = node.getAttribute('data-node-kind-label');"
        )
        if finder not in html:
            return "finder semanticType does not prefer the label attr"
        if "var typeLabel = item.node.getAttribute('data-node-kind-label')" not in html:
            return "finder meta title-cases the custom label"
        lens = (
            "var labeled = node.getAttribute('data-node-kind-label');\n"
            "          var value = labeled || node.getAttribute('data-node-kind') || 'neutral';"
        )
        if lens not in html:
            return "lens does not group by the label attr"
        return None
    finally:
        _unlink_quiet(fixture)
        _unlink_quiet(html_path)
        _unlink_quiet(map_path)


def _restore_texts(root: Path, originals: dict[str, str]) -> None:
    for rel, text in originals.items():
        _write_bytes_atomic(root / rel, text.encode("utf-8"))


def apply_archify_kind_patch(archify_mjs: str | None) -> str:
    """Patch the resolved tree. Never raises. Sets the status globals."""
    global _archify_patch_note, _archify_patch_state
    try:
        note, state = _apply_archify_kind_patch(archify_mjs)
    except Exception as e:
        note = f"archify patch: not patched (patch error: {e})"
        state = "unpatched"
    _archify_patch_note = note
    _archify_patch_state = state
    return note


def _apply_archify_kind_patch(archify_mjs: str | None) -> tuple[str, str]:
    if os.environ.get("ARCHIFY_BENDWRIGHT_PATCH", "").strip() == "0":
        return "archify patch: opted out", "opted-out"
    if not archify_mjs:
        return "archify patch: not patched (no archify.mjs)", "unpatched"
    root = archify_skill_root(archify_mjs)
    version = read_installed_archify_version(archify_mjs)
    specs = _archify_patch_specs()
    rels = tuple(spec["path"] for spec in specs)
    hunk_sha = _hunk_set_sha(specs)
    current = _hash_map(root, rels)
    if current is None:
        missing = next((rel for rel in rels if not (root / rel).is_file()), rels[0])
        return f"archify patch: not patched (missing {missing})", "unpatched"

    state = _read_patch_state()
    record = state.get("hunks", {}).get(hunk_sha)
    if isinstance(record, dict):
        patched = record.get("patched_hashes")
        failed = record.get("failure_hashes")
        if patched == current:
            return "archify patch: patched", "patched"
        if isinstance(failed, dict) and failed == current:
            reason = record.get("failure_note") or "previous attempt failed"
            return f"archify patch: not patched ({reason})", "unpatched"

    version_bit = f"archify {version}" if version else "archify version unknown"
    if not _dir_writable(root):
        return (
            f"archify patch: not patched (archify patch skipped: {root} not writable)",
            "unpatched",
        )

    originals: dict[str, str] = {}
    patched_text: dict[str, str] = {}
    for spec in specs:
        rel = spec["path"]
        try:
            text = (root / rel).read_bytes().decode("utf-8")
        except (OSError, UnicodeError) as e:
            return f"archify patch: not patched (could not read {rel}: {e})", "unpatched"
        originals[rel] = text
        updated, err = _replace_anchors(text, spec["anchors"])
        if updated is None:
            note = f"anchor miss in {rel}: {err}"
            _record_patch_failure(hunk_sha, root, version, current, note)
            return f"archify patch: not patched ({note}; custom names shown in tooltips and page legend only)", "unpatched"
        patched_text[rel] = updated

    wrote: list[str] = []
    try:
        for rel, text in originals.items():
            backup = _backup_path(root / rel)
            if not backup.exists():
                _write_bytes_atomic(backup, text.encode("utf-8"))
        for rel, text in patched_text.items():
            _write_bytes_atomic(root / rel, text.encode("utf-8"))
            wrote.append(rel)
        reason = _smoke_kind_patch(archify_mjs)
        if reason:
            _restore_texts(root, originals)
            note = f"smoke failed: {reason}"
            _record_patch_failure(hunk_sha, root, version, current, note)
            return f"archify patch: not patched ({note}; custom names shown in tooltips and page legend only)", "unpatched"
        marker = root / _ARCHIFY_PATCH_MARKER
        _write_bytes_atomic(marker, f"{hunk_sha}\n".encode("utf-8"))
        patched_hashes = _hash_map(root, rels)
        if patched_hashes is None:
            raise OSError("patched files disappeared")
        # orig hashes are the backup bytes unpatch will restore.
        orig_hashes = {
            rel: _sha_bytes(_backup_path(root / rel).read_bytes()) for rel in rels
        }
        hunks = state.setdefault("hunks", {})
        hunks[hunk_sha] = {
            "root": str(root),
            "archify_version": version,
            "orig_hashes": orig_hashes,
            "patched_hashes": patched_hashes,
            "failure_hashes": None,
            "failure_note": None,
        }
        _write_patch_state(state)
    except OSError as e:
        if wrote:
            try:
                _restore_texts(root, originals)
            except OSError:
                pass
        _unlink_quiet(root / _ARCHIFY_PATCH_MARKER)
        note = f"archify patch skipped: {e}"
        return f"archify patch: not patched ({note})", "unpatched"
    return f"archify patch: applied now ({version_bit})", "applied"


def _matching_patch_record(state: dict[str, Any], root: Path, current: dict[str, str]) -> dict[str, Any] | None:
    hunks = state.get("hunks")
    if not isinstance(hunks, dict):
        return None
    root_s = str(root)
    fallback: dict[str, Any] | None = None
    for record in hunks.values():
        if not isinstance(record, dict):
            continue
        if record.get("patched_hashes") != current:
            continue
        if record.get("root") in (None, root_s):
            return record
        fallback = record
    return fallback


def unpatch_archify_main(cli_path: str | None) -> int:
    """Restore backups only when current hashes equal the recorded patched hashes."""
    try:
        archify, _detail = detect_archify(cli_path)
        if not archify:
            print(f"[{APP}] archify unpatch refused: no archify.mjs found", flush=True)
            return 2
        root = archify_skill_root(archify)
        specs = _archify_patch_specs()
        rels = tuple(spec["path"] for spec in specs)
        current = _hash_map(root, rels)
        if current is None:
            print(f"[{APP}] archify unpatch refused: patch targets missing in {root}", flush=True)
            return 2
        state = _read_patch_state()
        record = _matching_patch_record(state, root, current)
        if record is None:
            print(
                f"[{APP}] archify unpatch refused: current files do not match the recorded patched hashes",
                flush=True,
            )
            return 2
        orig = record.get("orig_hashes")
        if not isinstance(orig, dict):
            print(
                f"[{APP}] archify unpatch refused: recorded patch has no original hashes",
                flush=True,
            )
            return 2
        payloads: dict[str, bytes] = {}
        for rel in rels:
            backup = _backup_path(root / rel)
            if not backup.is_file():
                print(
                    f"[{APP}] archify unpatch refused: backup missing for {rel}",
                    flush=True,
                )
                return 2
            data = backup.read_bytes()
            if _sha_bytes(data) != orig.get(rel):
                print(
                    f"[{APP}] archify unpatch refused: backup does not match the recorded original for {rel}",
                    flush=True,
                )
                return 2
            payloads[rel] = data
        if not _dir_writable(root):
            print(
                f"[{APP}] archify unpatch refused: {root} not writable",
                flush=True,
            )
            return 2
        for rel, data in payloads.items():
            _write_bytes_atomic(root / rel, data)
        marker = root / _ARCHIFY_PATCH_MARKER
        if marker.exists():
            _unlink_quiet(marker)
        print(f"[{APP}] archify unpatch: restored {len(rels)} files in {root}", flush=True)
        return 0
    except Exception as e:
        print(f"[{APP}] archify unpatch refused: {e}", flush=True)
        return 2


