SUPPORTED_TYPES = {
    "workflow": "workflow",
    # future: "architecture": "architecture",
}


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    p = argparse.ArgumentParser(
        prog=APP,
        description=(
            "Local offline editor for Archify diagram IR JSON. "
            "User data (icons, type library, archify patch state) lives in "
            "bendwright-data/ next to this script. Set BENDWRIGHT_DATA_DIR to "
            "an absolute path to override."
        ),
    )
    p.add_argument(
        "type_or_path",
        nargs="?",
        default=None,
        help='diagram type ("workflow") or path to IR JSON; omit both for empty start',
    )
    p.add_argument(
        "path",
        nargs="?",
        default=None,
        help="path to the IR JSON file (when type is given first)",
    )
    p.add_argument(
        "--type",
        dest="type_override",
        default=None,
        help="diagram type override (otherwise inferred from the file)",
    )
    p.add_argument(
        "--archify",
        default=None,
        help="path to archify.mjs (explicit override; auto-detect otherwise)",
    )
    p.add_argument(
        "--port",
        type=int,
        default=8770,
        help="loopback port (default 8770)",
    )
    p.add_argument(
        "--keep-alive",
        action="store_true",
        help="disable auto-exit when the browser disconnects (SSE presence still served)",
    )
    p.add_argument(
        "--unpatch-archify",
        action="store_true",
        help="restore the resolved archify tree from .bendwright-orig backups",
    )
    return p.parse_args(argv)


def _presence_watchdog() -> None:
    """Shut down only after every /api/alive connection has been gone for GRACE.

    Does not arm on GET / and never takes _state_lock. --keep-alive disables this.
    """
    global _httpd
    while True:
        time.sleep(1.0)
        if not _auto_exit:
            continue
        with _alive_lock:
            seen = _alive_seen
            active = _alive
            zero_ts = _last_zero_ts
        if not seen or active != 0 or zero_ts is None:
            continue
        if (time.monotonic() - zero_ts) > ALIVE_GRACE_S:
            httpd = _httpd
            if httpd is not None:
                httpd.shutdown()
            return


def _wait_http_ready(port: int) -> bool:
    """True once GET /api/brands answers, so archify can fetch brand PNGs."""
    deadline = time.time() + 5.0
    url = f"http://127.0.0.1:{port}/api/brands"
    while time.time() < deadline:
        try:
            with urllib.request.urlopen(url, timeout=0.3) as resp:
                if getattr(resp, "status", 200) == 200:
                    return True
        except (OSError, urllib.error.URLError, TimeoutError):
            time.sleep(0.05)
    return False


def main(argv: list[str] | None = None) -> int:
    global _file_path, _diagram_type, _doc, _had_trailing_newline, _archify_path, _httpd, _auto_exit, _listen_port
    global _sidecar, _sidecar_note, _sidecar_unreadable

    args = parse_args(argv)
    migrate_legacy_data_dir()
    if args.unpatch_archify:
        return unpatch_archify_main(args.archify)
    known = ", ".join(sorted(SUPPORTED_TYPES))
    file_path: Path | None = None
    dtype: str | None = None

    if args.path is not None:
        # Legacy: python bendwright.py workflow path.json
        if args.type_or_path not in SUPPORTED_TYPES:
            print(
                f"[{APP}] unknown type {args.type_or_path!r}; known: {known}",
                file=sys.stderr,
            )
            return 2
        dtype = SUPPORTED_TYPES[args.type_or_path]
        file_path = Path(args.path).resolve()
    elif args.type_or_path is not None:
        # One positional: path.json (or a bare type without path → error)
        token = args.type_or_path
        as_path = Path(token)
        if token in SUPPORTED_TYPES and not as_path.is_file():
            print(
                f"[{APP}] path required when type is given (got type {token!r} only)",
                file=sys.stderr,
            )
            return 2
        file_path = as_path.resolve()
    # else: no-arg empty start

    if args.type_override is not None and args.type_override not in SUPPORTED_TYPES:
        print(
            f"[{APP}] unknown --type {args.type_override!r}; known: {known}",
            file=sys.stderr,
        )
        return 2

    note_data_dir_writable()
    _archify_path, archify_msg = detect_archify(args.archify)
    note_archify_version(_archify_path)
    load_archify_catalog(_archify_path)
    icon_note = scan_user_icons()
    apply_archify_kind_patch(_archify_path)
    set_preview_html(None)
    print(f"[{APP}] archify: {archify_msg}", flush=True)
    if _archify_version_note:
        print(f"[{APP}] {_archify_version_note}", flush=True)
    if _archify_patch_note:
        print(f"[{APP}] {_archify_patch_note}", flush=True)
    if _data_dir_note:
        print(f"[{APP}] {_data_dir_note}", flush=True)
    if _catalog_note:
        print(f"[{APP}] {_catalog_note}", flush=True)
    if icon_note:
        print(f"[{APP}] {icon_note}", flush=True)

    if file_path is not None:
        if not file_path.is_file():
            print(f"[{APP}] file not found: {file_path}", file=sys.stderr)
            return 2
        doc, trailing = load_doc(file_path)
        if args.type_override is not None:
            dtype = SUPPORTED_TYPES[args.type_override]
        elif dtype is None:
            inferred = doc.get("diagram_type")
            if not isinstance(inferred, str) or not inferred.strip():
                print(
                    f"[{APP}] missing diagram_type in {file_path}",
                    file=sys.stderr,
                )
                return 2
            if inferred not in SUPPORTED_TYPES:
                print(
                    f"[{APP}] unsupported diagram_type {inferred!r}; known: {known}",
                    file=sys.stderr,
                )
                return 2
            dtype = SUPPORTED_TYPES[inferred]
        _file_path = file_path
        _diagram_type = dtype
        _doc = doc
        _had_trailing_newline = trailing
        _sidecar, _sidecar_note, _sidecar_unreadable = load_sidecar(file_path, doc)
    else:
        _file_path = None
        if args.type_override is not None:
            _diagram_type = SUPPORTED_TYPES[args.type_override]
        else:
            _diagram_type = "workflow"
        _doc = blank_workflow()
        _had_trailing_newline = True
        _sidecar = empty_sidecar()
        _sidecar_note = None
        _sidecar_unreadable = False

    # Bind before the initial deliver so archify can fetch /brand/<name>.png.
    _listen_port = args.port
    try:
        server = ThreadingHTTPServer(("127.0.0.1", args.port), Handler)
    except OSError as e:
        print(f"[{APP}] cannot bind 127.0.0.1:{args.port}: {e}", file=sys.stderr)
        return 2
    server.daemon_threads = True
    _httpd = server
    _listen_port = int(server.server_address[1])
    serve_thread = threading.Thread(target=server.serve_forever, name="bendwright-http")
    serve_thread.start()
    try:
        if not _wait_http_ready(_listen_port):
            print(
                f"[{APP}] HTTP server did not accept connections on port {_listen_port}",
                file=sys.stderr,
            )

        if _archify_path and isinstance(_doc, dict) and _doc:
            if file_path is not None:
                rendered = deliver_saved_file(
                    _archify_path, _diagram_type, file_path, None, _sidecar
                )
            else:
                rendered = deliver_preview_doc(
                    _archify_path, _diagram_type, _doc, True, _sidecar
                )
            html, note = rendered if isinstance(rendered, tuple) else (None, "deliver failed")
            miss = _markup_miss_from_note(note if isinstance(note, str) else None)
            with _state_lock:
                if html is not None:
                    set_preview_html(html)
                if miss:
                    _sidecar_note = _join_notes(_sidecar_note, miss)
            if html is not None:
                print(f"[{APP}] initial preview rendered", flush=True)
                if note:
                    print(f"[{APP}] {note}", flush=True)
            else:
                print(
                    f"[{APP}] initial preview unavailable: {note or 'deliver failed'}",
                    flush=True,
                )

        url = f"http://127.0.0.1:{_listen_port}/"
        if file_path is not None:
            print(f"[{APP}] {url}  editing {file_path}", flush=True)
        else:
            print(f"[{APP}] {url}  unsaved new diagram (Save to choose a path)", flush=True)
        _auto_exit = not args.keep_alive
        if args.keep_alive:
            print(f"[{APP}] auto-exit off (--keep-alive)", flush=True)
        try:
            webbrowser.open(url)
        except Exception:
            pass

        threading.Thread(target=_presence_watchdog, name="presence-watchdog", daemon=True).start()
        while serve_thread.is_alive():
            serve_thread.join(0.5)
    except KeyboardInterrupt:
        print(f"\n[{APP}] stopped", flush=True)
    finally:
        if serve_thread.is_alive():
            server.shutdown()
            serve_thread.join(timeout=5)
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
